);

create unique index uk_claims_token_core on public.claims (token_core);
create index idx_claims_status on public.claims (status);
create index idx_claims_card on public.claims (card_id);
create index idx_claims_event on public.claims (event_id);

create table public.player_achievements (
    id          uuid primary key,
    player_id   uuid not null references public.profiles (id) on delete cascade,
    code        text not null,
    unlocked_at timestamptz not null default now(),
    constraint uk_player_achievements_player_code unique (player_id, code)
);

create index idx_player_achievements_player on public.player_achievements (player_id);

alter table public.claims enable row level security;
alter table public.events enable row level security;
alter table public.player_achievements enable row level security;

-- claims are minted/consumed by the claim Edge Function via service role.
-- players may read the claims they have already claimed (claim history).
create policy claims_select_own on public.claims for select
using (claimed_by = auth.uid() or public.is_admin());

-- events: everyone reads; only admins manage.
create policy events_select_all on public.events for select using (true);
create policy events_admin_all on public.events for all using (public.is_admin()) with check (public.is_admin());

-- achievements are written by definer functions (sweep) and read by the owner.
create policy player_achievements_select_own on public.player_achievements for select
using (player_id = auth.uid() or public.is_admin());
create policy player_achievements_insert_own on public.player_achievements for insert
with check (player_id = auth.uid());

-- ******************** FILE: migrations/20260923000006_game_functions.sql ********************
-- Campus Forge → Supabase
-- Migration 7/9: core game functions called by Edge Functions, the
-- battle-engine (service role), and direct client RPC.
-- Deadlock-avoidance rule preserved: row locks in sorted-UUID order.
--
-- Faithful ports of the Java semantics (ClaimService, CollectionService,
-- TradeService, MatchManager, FeedService). The resulting rules are
-- documented in DOCS/game-rules.md and DOCS/database.md.

-- ---------------------------------------------------------------
-- Feed ring (moved here from migration 8/9 so the definer functions
-- below can write feed rows). Mirrors the old in-memory CAPACITY=50.
-- ---------------------------------------------------------------
create table public.activity_feed (
    id         bigint generated always as identity primary key,
    type       text not null,
    text       text not null,
    player_id  uuid references public.profiles (id) on delete set null,
    card_id    uuid references public.cards (id) on delete set null,
    created_at timestamptz not null default now()
);

create index idx_activity_feed_created on public.activity_feed (created_at desc);

alter table public.activity_feed enable row level security;
create policy activity_feed_select_all on public.activity_feed for select using (true);

create or replace function public.prune_feed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    delete from public.activity_feed
     where id not in (
        select id from public.activity_feed order by id desc limit 50
     );
    return null;
end;
$$;

create trigger trg_feed_prune
after insert on public.activity_feed
for each statement execute function public.prune_feed();

create or replace function public.add_feed_entry(p_type text, p_text text, p_player uuid default null, p_card uuid default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    insert into public.activity_feed (type, text, player_id, card_id)
    values (p_type, p_text, p_player, p_card);
end;
$$;

revoke all on function public.add_feed_entry(text, text, uuid, uuid) from public;
grant execute on function public.add_feed_entry(text, text, uuid, uuid) to service_role;

alter publication supabase_realtime add table public.activity_feed;

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------
-- unique_physical_uuid: UUID.nameUUIDFromBytes("cf-unique:" + core),
-- the deterministic physical identity of a UNIQUE card so a QR token
-- maps to exactly one serialized copy (Java ClaimService.physicalUuidFor).
-- MD5 with version-3 + IETF-variant bits set.
-- ---------------------------------------------------------------
create or replace function public.unique_physical_uuid(p_core text)
returns uuid
language plpgsql
immutable
as $$
declare
    v bytea := decode(md5('cf-unique:' || p_core), 'hex');
    hex text;
begin
    v := set_byte(v, 6, (get_byte(v, 6) & 15) | 48);
    v := set_byte(v, 8, (get_byte(v, 8) & 63) | 128);
    hex := encode(v, 'hex');
    return (substr(hex, 1, 8) || '-' || substr(hex, 9, 4) || '-' ||
            substr(hex, 13, 4) || '-' || substr(hex, 17, 4) || '-' ||
            substr(hex, 21, 12))::uuid;
end;
$$;

-- ---------------------------------------------------------------
-- card_print_core: deterministic QR print core, exact port of
-- Java ClaimService.deterministicCore: SHA-256("cf-print:"+cardId),
-- first 6 bytes as a 48-bit big-endian long, then 12 iterations of
-- (v % 31) taking the next char from the 31-char token alphabet.
-- ---------------------------------------------------------------
create or replace function public.card_print_core(p_card_id uuid)
returns text
language plpgsql
stable
as $$
declare
    d        bytea := digest(convert_to('cf-print:' || p_card_id, 'UTF8'), 'sha256');
    alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
    v        bigint;
    sb       text := '';
begin
    v := (get_byte(d, 0)::bigint << 40)
      | (get_byte(d, 1)::bigint << 32)
      | (get_byte(d, 2)::bigint << 24)
      | (get_byte(d, 3)::bigint << 16)
      | (get_byte(d, 4)::bigint << 8)
      |  get_byte(d, 5)::bigint;
    for i in 0..11 loop
        sb := sb || substr(alphabet, (v % length(alphabet))::int + 1, 1);
        v := v / length(alphabet);
    end loop;
    return sb;
end;
$$;

-- ---------------------------------------------------------------
-- apply_claim: consume a QR token. Faithful port of ClaimService.claim
-- + CollectionService.discover (+ MatchManager reward semantics on XP).
-- Signature check happens in the Edge Function BEFORE this RPC; this
-- function is service-role only so clients cannot bypass verification.
--
-- Error codes → HTTP mapping (EF):
--   CF404 → 404, CF409 → 409, CF410 → 410, CF403 → 403
--
-- pkgs semantics:
--   UNLOCK token claims  → reusable per player; each player gets unlock +
--                          XP on first discovery, then count++ / alreadyOwned
--                          (0 XP) afterwards. Token stays ACTIVE.
--   UNIQUE token claims  → one-shot; first claimer gets the serialized copy
--                          (deterministic physical uuid + max(serial)+1) and
--                          XP, token flips to CLAIMED; anyone else → 409.
--   UNLIMITED claims     → discovery count only, always alreadyOwned (0 XP).
-- ---------------------------------------------------------------
create or replace function public.apply_claim(p_core text, p_player uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    c          public.claims%rowtype;
    v_card     public.cards%rowtype;
    v_count    bigint;
    v_owns     boolean;
    v_unlocked boolean := false;
    v_xp       bigint := 0;
    v_phys     uuid := null;
    v_serial   integer;
    v_bonus    numeric := 1.00;
begin
    select * into c from public.claims where token_core = p_core for update;
    if not found then
        raise exception 'Claim token not found: %', p_core using errcode = 'CF404';
    end if;

    select * into v_card from public.cards where id = c.card_id;
    if not found then
        raise exception 'unknown card' using errcode = 'CF404';
    end if;

    -- status gate, in ClaimService order
    if c.status = 'REVOKED' then
        raise exception 'Claim token has been revoked' using errcode = 'CF410';
    end if;
    if c.expires_at is not null and c.expires_at < now() then
        update public.claims set status = 'EXPIRED' where id = c.id;
        raise exception 'Claim token has expired' using errcode = 'CF410';
    end if;
    if v_card.ownership_type = 'UNIQUE' and c.claimed_by is not null then
        raise exception 'This unique card has already been claimed' using errcode = 'CF409';
    end if;
    if c.status <> 'ACTIVE' then
        raise exception 'Claim token is no longer active' using errcode = 'CF410';
    end if;

    -- discovery always bumps (CollectionService.discover)
    insert into public.discoveries (id, player_id, card_id, count, last_discovered)
    values (gen_random_uuid(), p_player, c.card_id, 1, now())
    on conflict on constraint uk_discoveries_player_card do update
    set count = public.discoveries.count + 1,
        last_discovered = now();

    select d.count into v_count
      from public.discoveries d
     where d.player_id = p_player and d.card_id = c.card_id;

    -- first active event by start time wins (EventService.activeEvent)
    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.active = true and e.start_time <= now() and e.end_time >= now()
     order by e.start_time
     limit 1;
    if not found then
        v_bonus := 1.00;
    end if;

    -- ownership gate (CollectionService.owns): UNLIMITED always owned
    v_owns := (v_card.ownership_type = 'UNLIMITED')
           or (v_card.ownership_type = 'UNLOCK'
               and exists (select 1 from public.player_unlocks ul
                            where ul.player_id = p_player and ul.card_id = v_card.id))
           or (v_card.ownership_type = 'UNIQUE'
               and exists (select 1 from public.unique_cards uq
                            where uq.owner_id = p_player and uq.card_id = v_card.id));

    if not v_owns then
        if v_card.ownership_type = 'UNLOCK' then
            insert into public.player_unlocks (id, player_id, card_id, unlocked_at)
            values (gen_random_uuid(), p_player, v_card.id, now())
            on conflict on constraint uk_player_unlocks_player_card do nothing;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        elsif v_card.ownership_type = 'UNIQUE' then
            select coalesce(max(uq.serial_number), 0) + 1 into v_serial
              from public.unique_cards uq where uq.card_id = v_card.id;
            v_phys := public.unique_physical_uuid(c.token_core);
            insert into public.unique_cards (physical_uuid, owner_id, card_id, serial_number, history)
            values (v_phys, p_player, c.card_id, v_serial, 'claimed via discovery')
            on conflict (physical_uuid) do nothing;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        end if;
    end if;

    if v_unlocked then
        update public.profiles set experience = experience + v_xp where id = p_player;
        perform public.add_feed_entry('DISCOVERY', 'discovered ' || v_card.forge_name, p_player, v_card.id);
    else
        perform public.add_feed_entry('DISCOVERY', 'scanned ' || v_card.forge_name, p_player, v_card.id);
    end if;

    -- claim bookkeeping: UNIQUE flips to CLAIMED (one-shot); others keep
    -- ACTIVE but record the last claimer (reusable per player).
    if v_card.ownership_type = 'UNIQUE' then
        update public.claims set status = 'CLAIMED', claimed_by = p_player, claimed_at = now()
         where id = c.id;
    else
        update public.claims set claimed_by = p_player, claimed_at = now() where id = c.id;
    end if;

    return jsonb_build_object(
        'card', jsonb_build_object(
            'id', v_card.id,
            'oracleId', v_card.oracle_id,
            'forgeName', v_card.forge_name,
            'rarity', v_card.rarity,
            'ownershipType', v_card.ownership_type,
            'setCode', v_card.set_code,
            'manaValue', v_card.mana_value,
            'types', v_card.types,
            'colors', v_card.colors,
            'imageUrl', v_card.image_url,
            'discoverable', v_card.discoverable,
            'spawnRegion', v_card.spawn_region,
            'weight', v_card.weight,
            'commanderEligible', v_card.commander_eligible
        ),
        'unlocked', v_unlocked,
        'alreadyOwned', (not v_unlocked),
        'discoveryCount', v_count,
        'experienceAwarded', v_xp,
        'token', c.token,
        'building', c.building,
        'physicalUuid', v_phys
    );
end;
$$;

revoke all on function public.apply_claim(text, uuid) from public;
grant execute on function public.apply_claim(text, uuid) to service_role;

-- ---------------------------------------------------------------
-- accept_trade: receiver accepts. actor = auth.uid() (SECURITY DEFINER +
-- RLS bypass still cannot forge the actor). Faithful port of
-- TradeService.accept: lock pending trade, participant + role + status +
-- TTL checks, lock all involved cards one-by-one in sorted-UUID order,
-- re-verify ownership, swap owners, append history line (display names,
-- "\n"-joined), publish the trade feed entry.
-- ---------------------------------------------------------------
create or replace function public.accept_trade(p_trade uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    t              public.trades%rowtype;
    v_card_uuid    uuid;
    v_side         text;
    v_from_name    text;
    v_to_name      text;
    v_now          timestamptz := now();
    v_sender_name  text;
    v_receiver_name text;
    v_actor        uuid := auth.uid();
begin
    select * into t from public.trades where id = p_trade for update;
    if not found then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if v_actor <> t.sender_id and v_actor <> t.receiver_id then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if v_actor = t.sender_id then
        raise exception 'Only the receiver can perform this action on the trade' using errcode = 'CF403';
    end if;
    if t.status <> 'PENDING' then
        raise exception 'Trade is already %', lower(t.status) using errcode = 'CF409';
    end if;
    if t.expires_at < v_now then
        update public.trades set status = 'EXPIRED', resolved_at = v_now where id = t.id;
        raise exception 'Trade has expired' using errcode = 'CF410';
    end if;

    select display_name into v_sender_name   from public.profiles where id = t.sender_id;
    select display_name into v_receiver_name from public.profiles where id = t.receiver_id;

    -- lock every involved card in sorted-UUID order (deadlock avoidance)
    for v_card_uuid in
        select tc.physical_uuid
          from public.trade_cards tc
         where tc.trade_id = t.id
         order by tc.physical_uuid
    loop
        perform 1 from public.unique_cards where physical_uuid = v_card_uuid for update;
    end loop;

    -- ownership re-verification (TradeService.accept)
    for v_card_uuid in
        select tc.physical_uuid
          from public.trade_cards tc
         where tc.trade_id = t.id
         order by tc.physical_uuid
    loop
        select side into v_side from public.trade_cards where trade_id = t.id and physical_uuid = v_card_uuid;
        if (v_side = 'OFFERED'
            and exists (select 1 from public.unique_cards
                         where physical_uuid = v_card_uuid and owner_id <> t.sender_id))
           or (v_side = 'REQUESTED'
               and exists (select 1 from public.unique_cards
                            where physical_uuid = v_card_uuid and owner_id <> t.receiver_id)) then
            raise exception 'Ownership changed; trade no longer valid' using errcode = 'CF409';
        end if;
    end loop;

    -- swap owners + append history (display names, "\n"-joined)
    for v_card_uuid in
        select tc.physical_uuid
          from public.trade_cards tc
         where tc.trade_id = t.id
         order by tc.physical_uuid
    loop
        select side into v_side from public.trade_cards where trade_id = t.id and physical_uuid = v_card_uuid;
        if v_side = 'OFFERED' then
            v_from_name := v_sender_name;
            v_to_name   := v_receiver_name;
        else
            v_from_name := v_receiver_name;
            v_to_name   := v_sender_name;
        end if;
        update public.unique_cards
           set owner_id = case when v_side = 'OFFERED' then t.receiver_id else t.sender_id end,
               history = coalesce(nullif(history, ''), '')
                          || case when history is null or history = '' then '' else E'\n' end
                          || to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS') || ': '
                          || v_from_name || ' → ' || v_to_name || ' via trade ' || t.id
         where physical_uuid = v_card_uuid;
    end loop;

    update public.trades set status = 'ACCEPTED', resolved_at = v_now where id = t.id;

    perform public.add_feed_entry('TRADE', 'traded unique cards with ' || v_receiver_name, t.sender_id);

    return 'ACCEPTED';
end;
$$;

revoke all on function public.accept_trade(uuid) from public;
grant execute on function public.accept_trade(uuid) to authenticated;
grant execute on function public.accept_trade(uuid) to service_role;

-- decline (receiver) / cancel (sender) with the same role + TTL rules.
create or replace function public.resolve_trade(p_trade uuid, p_action text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    t            public.trades%rowtype;
    v_now        timestamptz := now();
    v_actor      uuid := auth.uid();
begin
    if p_action not in ('DECLINED', 'CANCELLED') then
        raise exception 'unknown action %', p_action using errcode = 'CF400';
    end if;

    select * into t from public.trades where id = p_trade for update;
    if not found then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if v_actor <> t.sender_id and v_actor <> t.receiver_id then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if p_action = 'DECLINED' and v_actor = t.sender_id then
        raise exception 'Only the receiver can perform this action on the trade' using errcode = 'CF403';
    end if;
    if p_action = 'CANCELLED' and v_actor = t.receiver_id then
        raise exception 'Only the sender can perform this action on the trade' using errcode = 'CF403';
    end if;
    if t.status <> 'PENDING' then
        raise exception 'Trade is already %', lower(t.status) using errcode = 'CF409';
    end if;
    if t.expires_at < v_now then
        update public.trades set status = 'EXPIRED', resolved_at = v_now where id = t.id;
        raise exception 'Trade has expired' using errcode = 'CF410';
    end if;

    update public.trades set status = p_action, resolved_at = v_now where id = t.id;
    return p_action;
end;
$$;

revoke all on function public.resolve_trade(uuid, text) from public;
grant execute on function public.resolve_trade(uuid, text) to authenticated;
grant execute on function public.resolve_trade(uuid, text) to service_role;

-- create trade from the client (RPC); sender = auth.uid(). Faithful port of
-- TradeService.create + validateBundles: no self-trade, no duplicate cards
-- in a bundle, no offered∩requested overlap, sender owns offered,
-- receiver owns requested, receiver exists.
create or replace function public.create_trade(
    p_receiver uuid,
    p_offered uuid[],   -- sender-owned unique card physical uuids
    p_requested uuid[]  -- receiver-owned unique card physical uuids
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_trade  uuid := gen_random_uuid();
    v_card   uuid;
    v_sender uuid := auth.uid();
    v_name   text;
begin
    if p_receiver = v_sender then
        raise exception 'You cannot trade with yourself' using errcode = 'CF400';
    end if;
    if not exists (select 1 from public.profiles where id = p_receiver) then
        raise exception 'Receiver not found' using errcode = 'CF404';
    end if;
    if (array_length(p_offered, 1) is null or array_length(p_offered, 1) = 0)
       and (array_length(p_requested, 1) is null or array_length(p_requested, 1) = 0) then
        raise exception 'Empty trade' using errcode = 'CF400';
    end if;

    -- no duplicates within a bundle; no overlap between bundles
    if p_offered is not null
       and (select count(*) from unnest(p_offered) x) <> (select count(distinct x) from unnest(p_offered) x) then
        raise exception 'Duplicate offered card in bundle' using errcode = 'CF400';
    end if;
    if p_requested is not null
       and (select count(*) from unnest(p_requested) x) <> (select count(distinct x) from unnest(p_requested) x) then
        raise exception 'Duplicate requested card in bundle' using errcode = 'CF400';
    end if;
    if p_offered is not null and p_requested is not null
       and exists (select 1 from unnest(p_offered) o join unnest(p_requested) r on r = o) then
        raise exception 'A card cannot be both offered and requested' using errcode = 'CF400';
    end if;

    insert into public.trades (id, sender_id, receiver_id, status)
    values (v_trade, v_sender, p_receiver, 'PENDING');

    if p_offered is not null then
        foreach v_card in array p_offered loop
            select forge_name into v_name from public.cards c
              join public.unique_cards uq on uq.card_id = c.id
             where uq.physical_uuid = v_card;
            if not found then
                raise exception 'Offered unique card not found: %', v_card using errcode = 'CF404';
            end if;
            if not exists (select 1 from public.unique_cards where physical_uuid = v_card and owner_id = v_sender) then
                raise exception 'You do not own offered card: %', v_name using errcode = 'CF400';
            end if;
            insert into public.trade_cards (id, trade_id, side, physical_uuid)
            values (gen_random_uuid(), v_trade, 'OFFERED', v_card);
        end loop;
    end if;

    if p_requested is not null then
        foreach v_card in array p_requested loop
            select forge_name into v_name from public.cards c
              join public.unique_cards uq on uq.card_id = c.id
             where uq.physical_uuid = v_card;
            if not found then
                raise exception 'Requested unique card not found: %', v_card using errcode = 'CF404';
            end if;
            if not exists (select 1 from public.unique_cards where physical_uuid = v_card and owner_id = p_receiver) then
                raise exception 'Receiver does not own requested card: %', v_name using errcode = 'CF400';
            end if;
            insert into public.trade_cards (id, trade_id, side, physical_uuid)
            values (gen_random_uuid(), v_trade, 'REQUESTED', v_card);
        end loop;
    end if;

    return v_trade;
end;
$$;

revoke all on function public.create_trade(uuid, uuid[], uuid[]) from public;
grant execute on function public.create_trade(uuid, uuid[], uuid[]) to authenticated;
grant execute on function public.create_trade(uuid, uuid[], uuid[]) to service_role;

-- ---------------------------------------------------------------
-- record_match_result: called by battle-engine (service role) when a match
-- ends. Winner gets XP (round(50 * bonus)); bonus comes from the match's
-- event if currently active (MatchManager.rewardWinner), else 50.
-- Idempotent on already-finished/conceded matches.
-- ---------------------------------------------------------------
create or replace function public.record_match_result(
    p_match     uuid,
    p_winner    uuid,
    p_win_cond  text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    m       public.matches%rowtype;
    v_xp    bigint := 50;
    v_bonus numeric := 1.00;
begin
    select * into m from public.matches where id = p_match for update;
    if not found then
        raise exception 'Match not found: %', p_match using errcode = 'CF404';
    end if;
    if m.status in ('FINISHED', 'CONCEDED') then
        return; -- idempotent
    end if;

    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.id = m.event_id
       and e.active = true and e.start_time <= now() and e.end_time >= now();
    if found then
        v_xp := round(50 * v_bonus)::bigint;
    end if;

    update public.matches
       set status = case when m.status = 'CONCEDED' then 'CONCEDED' else 'FINISHED' end,
           winner_id = p_winner,
           win_condition = coalesce(p_win_cond, m.win_condition),
           ended_at = now()
     where id = p_match;

    if p_winner is not null then
        update public.profiles set experience = experience + v_xp where id = p_winner;
        perform public.add_feed_entry('DISCOVERY', 'won a battle (+' || v_xp || ' XP)', p_winner);
    end if;
end;
$$;

revoke all on function public.record_match_result(uuid, uuid, text) from public;
grant execute on function public.record_match_result(uuid, uuid, text) to service_role;

-- ******************** FILE: migrations/20260923000007_analytics_feed.sql ********************
-- Campus Forge → Supabase
-- Migration 8/9: read-path analytics functions.
-- (activity_feed + add_feed_entry + prune + realtime publication moved to
-- migration 7/9 so the game definer functions can write feed rows.)

-- ---------------------------------------------------------------
-- Analytics
-- ---------------------------------------------------------------

-- leaderboard, filtered by cohort/department (mirrors GET /api/v1/leaderboard).
create or replace function public.leaderboard(
    p_degree_level text default null,
    p_specialization text default null,
    p_department text default null,
    p_limit integer default 100
)
returns table (
    player_id      uuid,
    display_name   text,
    degree_level   text,
    specialization text,
    department     text,
    experience     bigint,
    level          integer,
    wins           bigint
)
language sql
stable
as $$
    select
        p.id,
        p.display_name,
        p.degree_level,
        p.specialization,
        public.department_of(p.specialization) as department,
        p.experience,
        public.compute_level(p.experience) as level,
        (select count(*) from public.matches m where m.winner_id = p.id and m.status in ('FINISHED','CONCEDED')) as wins
    from public.profiles p
    where p.banned = false
      and (p_degree_level is null     or p.degree_level = upper(p_degree_level))
      and (p_specialization is null   or p.specialization = upper(p_specialization))
      and (p_department is null       or public.department_of(p.specialization) = upper(p_department))
    order by p.experience desc, p.display_name asc
    limit least(greatest(p_limit, 1), 100);
$$;

grant execute on function public.leaderboard(text, text, text, integer) to authenticated;
grant execute on function public.leaderboard(text, text, text, integer) to anon;

-- popular decks (mirrors GET /api/v1/analytics/decks): count by ownership.
create or replace function public.popular_decks(p_limit integer default 10)
returns table (
    deck_id   uuid,
    name      text,
    format_code text,
    player_name text,
    uses      bigint
)
language sql
stable
as $$
    select
        d.id,
        d.name,
        d.format_code,
        (select display_name from public.profiles where id = d.player_id) as player_name,
        coalesce((select count(*) from public.matches m where m.deck1_id = d.id or m.deck2_id = d.id), 0) as uses
    from public.decks d
    order by uses desc, d.name asc
    limit least(greatest(p_limit, 1), 100);
$$;

grant execute on function public.popular_decks(integer) to authenticated;
grant execute on function public.popular_decks(integer) to anon;

-- active buildings from claims (mirrors GET /api/v1/analytics/buildings).
create or replace function public.active_buildings(p_limit integer default 10)
returns table (
    building text,
    claims   bigint
)
language sql
stable
as $$
    select coalesce(nullif(building, ''), 'Unknown') as building, count(*) as claims
    from public.claims
    where claimed_by is not null
    group by building
    order by claims desc
    limit least(greatest(p_limit, 1), 100);
$$;

grant execute on function public.active_buildings(integer) to authenticated;
grant execute on function public.active_buildings(integer) to anon;

-- profile stats (mirrors GET /players/{id}/stats).
create or replace function public.profile_stats(p_player uuid)
returns table (
    player_id        uuid,
    display_name     text,
    degree_level     text,
    specialization   text,
    department       text,
    role             text,
    experience       bigint,
    level            integer,
    cards_found      bigint,
    unlock_count     bigint,
    unique_count     bigint,
    achievements     bigint,
    wins             bigint,
    losses           bigint,
    buildings_visited text[]
)
language sql
stable
as $$
    select
        p.id,
        p.display_name,
        p.degree_level,
        p.specialization,
        public.department_of(p.specialization),
        p.role,
        p.experience,
        public.compute_level(p.experience),
        (select coalesce(sum(count), 0) from public.discoveries where player_id = p.id) as cards_found,
        (select count(*) from public.player_unlocks where player_id = p.id) as unlock_count,
        (select count(*) from public.unique_cards where owner_id = p.id) as unique_count,
        (select count(*) from public.player_achievements where player_id = p.id) as achievements,
        (select count(*) from public.matches where winner_id = p.id and status in ('FINISHED','CONCEDED')) as wins,
        (select count(*) from public.matches where (player1_id = p.id or player2_id = p.id) and winner_id is not null and winner_id <> p.id and status in ('FINISHED','CONCEDED')) as losses,
        (select array_agg(distinct building order by building) from public.claims where claimed_by = p.id and building is not null) as buildings_visited
    from public.profiles p
    where p.id = p_player;
$$;

grant execute on function public.profile_stats(uuid) to authenticated;
grant execute on function public.profile_stats(uuid) to anon;

-- ******************** FILE: migrations/20260923000008_deck_validation.sql ********************
-- Campus Forge → Supabase
-- Migration 9/9: deck validation (mirrors DeckValidationService).
-- Returns the same problem vocabulary: NOT_ENOUGH_CARDS, TOO_MANY_COPIES,
-- NOT_OWNED, FORMAT_ILLEGAL, NOT_IN_EVENT, BANNED_CARD, INVALID_COHORT etc.

create type public.deck_problem as (
    severity text,
    code     text,
    message  text
);

-- validate a deck owned by the caller: size, copies, ownership, format legality,
-- and event allowed_sets (non-basic setCode must be in the active event).
-- Returns the list of problems; empty = valid.
create or replace function public.validate_deck(
    p_deck       uuid,
    p_event      uuid default null
)
returns setof public.deck_problem
language plpgsql
security definer
set search_path = public
as $$
declare
    d           public.decks%rowtype;
    f           public.formats%rowtype;
    v_total     integer;
    v_basic     boolean;
    v_allowed   jsonb;
    e           record;
    v_owner     uuid;
begin
    select * into d from public.decks where id = p_deck;
    if not found then
        return next row('ERROR', 'NOT_FOUND', 'deck not found')::public.deck_problem;
        return;
    end if;

    v_owner := d.player_id;

    -- total card count
    select coalesce(sum(dc.quantity), 0)::integer
    into v_total
    from public.deck_cards dc where dc.deck_id = p_deck;

    for e in
        select
            c.id as card_id, c.forge_name, c.ownership_type,
            c.set_code, c.types,
            dc.quantity,
            (case when c.ownership_type = 'UNLIMITED'
                  then true
                  else coalesce((select true from public.player_unlocks u where u.player_id = v_owner and u.card_id = c.id), false)
                      or exists (select 1 from public.unique_cards uc where uc.owner_id = v_owner and uc.card_id = c.id)
             end) as owned,
            (select count(*) from public.card_legalities cl
              where cl.card_id = c.id and cl.legality = 'BANNED') as banned_count
        from public.deck_cards dc
        join public.cards c on c.id = dc.card_id
        where dc.deck_id = p_deck
    loop
        if not e.owned then
            return next row('ERROR', 'NOT_OWNED', format('%s is not owned by the player', e.forge_name))::public.deck_problem;
        end if;

        select * into f from public.formats where code = d.format_code;
        -- copies check vs format.max_copies, except basics_unlimited basics
        select (b.types ilike '%Basic%') into v_basic from public.cards b where b.id = e.card_id;
        if not (f.basics_unlimited and v_basic)
           and e.quantity > f.max_copies
        then
            return next row('ERROR', 'TOO_MANY_COPIES', format('%s exceeds max copies of %s', e.forge_name, f.max_copies))::public.deck_problem;
        end if;

        if e.banned_count > 0 then
            return next row('ERROR', 'BANNED_CARD', format('%s is banned in %s', e.forge_name, f.name))::public.deck_problem;
        end if;

        -- event gate: non-basic setCode must be in the active event's allowed sets
        if p_event is not null then
            select allowed_sets_json::jsonb into v_allowed from public.events where id = p_event and active = true;
            if v_allowed is not null and not v_basic
               and (e.set_code is null or not (e.set_code = any (select jsonb_array_elements_text(v_allowed))))
            then
                return next row('ERROR', 'NOT_IN_EVENT', format('%s is not in the event allowed sets', e.forge_name))::public.deck_problem;
            end if;
        end if;
    end loop;

    if v_total < f.min_deck_size then
        return next row('WARNING', 'NOT_ENOUGH_CARDS', format('deck has %s cards, requires %s', v_total, f.min_deck_size))::public.deck_problem;
    end if;
end;
$$;

revoke all on function public.validate_deck(uuid, uuid) from public;
grant execute on function public.validate_deck(uuid, uuid) to authenticated;
grant execute on function public.validate_deck(uuid, uuid) to service_role;

-- ******************** FILE: migrations/20260923000009_print_catalog_helper.sql ********************
-- Campus Forge → Supabase
-- Migration 9/9: qr print-catalog helper used by the qr-catalog Edge Function.
-- Mirrors ClaimService.generatePrintCatalog: a deterministic token core per
-- card (card_print_core, migration 06) with an idempotent claim insert.
-- The signed full token (V1.<CORE>.<SIG>) is computed in the Edge Function,
-- which owns the HMAC secret; the postgres helper just guarantees a row exists.

create or replace function public.ensure_print_claim(
    p_card_id uuid,
    p_core    text,
    p_token   text
)
returns public.claims
language plpgsql
set search_path = public
as $$
declare
    v_claim public.claims;
    v_cnt   int;
begin
    select 1 into v_cnt from public.claims where token_core = p_core limit 1;
    if not found then
        insert into public.claims (id, token, token_core, card_id, status, created_at)
        values (gen_random_uuid(), p_token, p_core, p_card_id, 'ACTIVE', now())
        on conflict (token_core) do nothing;
    end if;

    select * into v_claim from public.claims where token_core = p_core limit 1;
    return v_claim;
end;
$$;

revoke all on function public.ensure_print_claim(uuid, text, text) from public;
grant execute on function public.ensure_print_claim(uuid, text, text) to service_role;

-- ******************** FILE: migrations/20260923000010_card_art_storage.sql ********************
-- Campus Forge → Supabase
-- Migration 10/10: storage bucket `card-art` for card images.
-- Replaces backend CardArtConfig (`file:../card-art/`). Public read so the
-- PWA can hotlink {bucket}/public/{slug}.jpg on GitHub Pages; uploads happen
-- via setup/download-card-art.ps1 with the service role key (RLS-bypassing).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('card-art', 'card-art', true, 52428800, array['image/jpeg', 'image/png'])
on conflict (id) do update
set public = true, file_size_limit = 52428800,
    allowed_mime_types = array['image/jpeg', 'image/png'];

-- Public read on objects in the bucket (anonymous download for <img> tags).
-- The select policy covers the browser fetching public URLs without auth.
do $$
begin
    if not exists (
        select 1 from pg_policies
        where schemaname = 'storage' and tablename = 'objects' and policyname = 'card-art public read'
    ) then
        create policy "card-art public read" on storage.objects
            for select to anon, authenticated
            using (bucket_id = 'card-art');
    end if;
end;
$$;

-- ******************** FILE: migrations/20260924000011_client_read_rpcs.sql ********************
-- Campus Forge → Supabase
-- Migration 11/11: client read RPCs.
--
-- RLS lets a player read their own rows, but the web client needs several
-- cross-player or denormalized reads that plain RLS blocks (RLS can only see
-- rows for auth.uid()). These are SECURITY DEFINER ports of the Java services
-- (LeaderboardService, PlayerStatsService, PlayerController, TradeService,
-- DeckValidationService, AchievementCatalog) so the PWA calls one RPC instead
-- of a stack of RLS-fenced selects.
--
-- Idempotent (create or replace + guarded ALTER) so it can be pasted straight
-- into the hosted-dashboard SQL Editor on top of the applied 00–10 migrations.

-- ---------------------------------------------------------------
-- Feed: denormalize player_name on activity_feed so both the REST-history
-- reads and Realtime pushes carry a display name without a join (the join
-- would hit profiles RLS for other players' rows).
-- ---------------------------------------------------------------
do $$
begin
    if not exists (
        select 1 from information_schema.columns
        where table_schema = 'public' and table_name = 'activity_feed' and column_name = 'player_name'
    ) then
        alter table public.activity_feed add column player_name text;
    end if;
end;
$$;

update public.activity_feed af
   set player_name = p.display_name
  from public.profiles p
 where p.id = af.player_id
   and (af.player_name is null or af.player_name = '');

create or replace function public.add_feed_entry(p_type text, p_text text, p_player uuid default null, p_card uuid default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    insert into public.activity_feed (type, text, player_id, card_id, player_name)
    values (
        p_type,
        p_text,
        p_player,
        p_card,
        case when p_player is null then null
             else (select display_name from public.profiles where id = p_player)
        end
    );
end;
$$;

revoke all on function public.add_feed_entry(text, text, uuid, uuid) from public;
grant execute on function public.add_feed_entry(text, text, uuid, uuid) to service_role;

-- ---------------------------------------------------------------
-- Achievement catalog (single source of truth, AchievementCatalog.java).
-- ---------------------------------------------------------------
create or replace function public.achievement_catalog()
returns table (
    code        text,
    name        text,
    description text,
    metric      text,
    threshold   integer
)
language sql
immutable
as $$
    values
        ('FIRST_DISCOVERY', 'First Discovery', 'Discover your first card.', 'DISCOVERIES', 1),
        ('EXPLORER', 'Explorer', 'Discover 25 cards.', 'DISCOVERIES', 25),
        ('COLLECTOR_I', 'Collector I', 'Own 25% of the card catalog.', 'COLLECTION_PCT', 25),
        ('COLLECTOR_II', 'Collector II', 'Own 50% of the card catalog.', 'COLLECTION_PCT', 50),
        ('COLLECTOR_III', 'Collector III', 'Own 75% of the card catalog.', 'COLLECTION_PCT', 75),
        ('COMPLETIONIST', 'Completionist', 'Own every card.', 'COLLECTION_PCT', 100),
        ('BATTLE_VETERAN', 'Battle Veteran', 'Win your first battle.', 'BATTLES_WON', 1),
        ('UNDEFEATED', 'Undefeated', 'Win every battle you finish.', 'UNDEFEATED', 1),
        ('RISING_STAR', 'Rising Star', 'Reach level 5.', 'LEVEL', 5),
        ('HALL_OF_FAME', 'Hall of Fame', 'Reach level 10.', 'LEVEL', 10),
        ('FIRST_TRADE', 'First Trade', 'Complete your first unique-card trade.', 'UNIQUE_TRADES', 1),
        ('MASTER_TRADER', 'Master Trader', 'Complete 5 unique-card trades.', 'UNIQUE_TRADES', 5);
$$;

-- ---------------------------------------------------------------
-- sweep_achievements: achievement unlock check, AchievementService.unlockFor
-- port. Runs at the top of my_profile_stats (like PlayerStatsService does
-- before badges). Security definer so it can write player_achievements.
-- ---------------------------------------------------------------
create or replace function public.sweep_achievements(p_player uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_level    integer;
    v_disc     bigint;
    v_played   integer;
    v_wins     integer;
    v_owned    integer;
    v_total    integer;
    v_comp     integer;
    v_trades   bigint;
    v_undef    integer;
    ac         record;
    v_value    bigint;
begin
    if p_player is null then
        return;
    end if;

    select public.compute_level(p.experience) into v_level
      from public.profiles p where p.id = p_player;
    if not found then
        return;
    end if;

    select coalesce(sum(count), 0) into v_disc
      from public.discoveries where player_id = p_player;

    select count(*) into v_played from public.matches
     where (player1_id = p_player or player2_id = p_player)
       and status in ('FINISHED', 'CONCEDED');
    select count(*) into v_wins from public.matches
     where winner_id = p_player and status in ('FINISHED', 'CONCEDED');

    select count(*) into v_total from public.cards;
    select count(distinct c.id) into v_owned from public.cards c
     where c.ownership_type = 'UNLIMITED'
        or exists (select 1 from public.player_unlocks u where u.player_id = p_player and u.card_id = c.id)
        or exists (select 1 from public.unique_cards uc where uc.owner_id = p_player and uc.card_id = c.id);

    v_comp := case when v_total = 0 then 0 else round(100.0 * v_owned / v_total)::integer end;

    select count(*) into v_trades from public.trades
     where status = 'ACCEPTED' and (sender_id = p_player or receiver_id = p_player);

    v_undef := case when v_played >= 1 and v_wins = v_played then 1 else 0 end;

    for ac in select * from public.achievement_catalog() loop
        v_value := case ac.metric
            when 'DISCOVERIES'    then v_disc
            when 'BATTLES_WON'    then v_wins
            when 'UNIQUE_TRADES'  then v_trades
            when 'LEVEL'          then v_level
            when 'COLLECTION_PCT' then v_comp
            when 'UNDEFEATED'     then v_undef
            else 0
        end;
        if v_value >= ac.threshold then
            insert into public.player_achievements (id, player_id, code)
            values (gen_random_uuid(), p_player, ac.code)
            on conflict on constraint uk_player_achievements_player_code do nothing;
        end if;
    end loop;
end;
$$;

revoke all on function public.sweep_achievements(uuid) from public;
grant execute on function public.sweep_achievements(uuid) to authenticated;
grant execute on function public.sweep_achievements(uuid) to service_role;

-- ---------------------------------------------------------------
-- my_profile_stats: GET /players/me/stats port (PlayerStatsService.myStats).
-- Sweeps achievements first, returns the full ProfileStatsDto payload as JSON
-- (badges resolved through achievement_catalog).
-- ---------------------------------------------------------------
create or replace function public.my_profile_stats(p_player uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid      uuid := coalesce(p_player, auth.uid());
    v_exp      bigint;
    v_level    integer;
    v_xp_next  bigint;
    v_disc     bigint;
    v_owned    integer;
    v_total    integer;
    v_comp     integer;
    v_colors   text[];
    v_buildings text[];
    v_played   integer;
    v_wins     integer;
    v_losses   integer;
    v_rate     integer;
    v_player   jsonb;
    v_badges   jsonb;
begin
    if v_uid is null then
        return null;
    end if;

    select
        p.experience,
        public.compute_level(p.experience),
        jsonb_build_object(
            'id', p.id, 'email', p.email, 'displayName', p.display_name, 'role', p.role,
            'avatar', p.avatar, 'studentId', p.student_id,
            'degreeLevel', p.degree_level, 'specialization', p.specialization,
            'experience', p.experience, 'level', public.compute_level(p.experience)
        )
    into v_exp, v_level, v_player
      from public.profiles p where p.id = v_uid;
    if not found then
        return null;
    end if;

    v_xp_next := greatest(0, (v_level * 100) - v_exp);

    select coalesce(sum(count), 0) into v_disc
      from public.discoveries where player_id = v_uid;

    select count(*) into v_total from public.cards;
    select count(distinct c.id) into v_owned from public.cards c
     where c.ownership_type = 'UNLIMITED'
        or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
        or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id);
    v_comp := case when v_total = 0 then 0 else round(100.0 * v_owned / v_total)::integer end;

    -- favoriteColors (PlayerMetrics.favoriteColors): top 3 identity colors by
    -- count across owned cards, count desc then color asc.
    select array_agg(ch) into v_colors
    from (
        select ch as ch, count(*) as cnt
        from (
            select distinct c.id, c.colors
            from public.cards c
            where (c.ownership_type = 'UNLIMITED'
                   or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
                   or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id))
              and c.colors is not null and c.colors <> ''
        ) owned,
        lateral unnest(string_to_array(replace(replace(replace(replace(replace(
            upper(owned.colors), 'W', 'W'), 'U', 'U'), 'B', 'B'), 'R', 'R'), 'G', 'G'), '')) as ch
        where ch in ('W', 'U', 'B', 'R', 'G')
        group by ch
        order by cnt desc, ch asc
        limit 3
    ) s;

    -- buildingsVisited (PlayerStatsService.buildingsVisited): distinct trimmed
    -- non-blank buildings from claimed spawns, sorted.
    select array_agg(b) into v_buildings
    from (
        select distinct trim(building) as b
        from public.claims
        where claimed_by = v_uid and building is not null and trim(building) <> ''
        order by b
    ) s;

    -- battleStats (PlayerMetrics.battleStats)
    select count(*) into v_played from public.matches
     where (player1_id = v_uid or player2_id = v_uid) and status in ('FINISHED', 'CONCEDED');
    select count(*) into v_wins from public.matches
     where winner_id = v_uid and status in ('FINISHED', 'CONCEDED');
    v_losses := v_played - v_wins;
    v_rate := case when v_played = 0 then 0 else round(100.0 * v_wins / v_played)::integer end;

    -- achievements: sweep, then badges resolved via the catalog.
    perform public.sweep_achievements(v_uid);
    select coalesce(jsonb_agg(jsonb_build_object('code', a.code, 'name', c.name, 'description', c.description)
                   order by a.unlocked_at), '[]'::jsonb)
      into v_badges
      from public.player_achievements a
      left join public.achievement_catalog() c on c.code = a.code
     where a.player_id = v_uid;

    return jsonb_build_object(
        'player', v_player,
        'experience', v_exp,
        'level', v_level,
        'experienceToNextLevel', v_xp_next,
        'collectionCompletionPercent', v_comp,
        'ownedCards', v_owned,
        'totalCards', v_total,
        'totalDiscoveries', v_disc,
        'favoriteColors', coalesce(v_colors, '{}'),
        'buildingsVisited', coalesce(v_buildings, '{}'),
        'battleStats', jsonb_build_object(
            'played', v_played, 'wins', v_wins, 'losses', v_losses, 'winRatePercent', v_rate
        ),
        'badges', v_badges
    );
end;
$$;

revoke all on function public.my_profile_stats(uuid) from public;
grant execute on function public.my_profile_stats(uuid) to authenticated;
grant execute on function public.my_profile_stats(uuid) to anon;
grant execute on function public.my_profile_stats(uuid) to service_role;

-- ---------------------------------------------------------------
-- leaderboard_full: GET /api/v1/leaderboard port (LeaderboardService). Three
-- metrics: 'level' (score=level, value=experience), 'collection'
-- (score=completion %, value=owned count), 'winrate' (score=win %, value=wins).
-- Banned players excluded; cohort/department filters; limit clamped 1..100.
-- Returns { rows: [{rank, playerId, displayName, avatar, degreeLevel,
-- specialization, score, value}], myRank } where myRank is the caller's
-- 1-based position over the FULL filtered set (may be beyond the limit/rows).
-- ---------------------------------------------------------------
create or replace function public.leaderboard_full(
    p_metric       text     default 'level',
    p_degree_level text     default null,
    p_specialization text   default null,
    p_department   text     default null,
    p_limit        integer  default 50
)
returns jsonb
language sql
security definer
set search_path = public
as $$
    with
    tot as (
        select count(*)::integer as n from public.cards
    ),
    base as (
        select
            p.id, p.display_name, p.avatar, p.degree_level, p.specialization,
            p.experience,
            public.compute_level(p.experience) as level,
            (select count(distinct c.id) from public.cards c
              where c.ownership_type = 'UNLIMITED'
                 or exists (select 1 from public.player_unlocks u where u.player_id = p.id and u.card_id = c.id)
                 or exists (select 1 from public.unique_cards uc where uc.owner_id = p.id and uc.card_id = c.id)
            ) as owned_count,
            (select count(*) from public.matches m
              where (m.player1_id = p.id or m.player2_id = p.id) and m.status in ('FINISHED', 'CONCEDED')) as played,
            (select count(*) from public.matches m
              where m.winner_id = p.id and m.status in ('FINISHED', 'CONCEDED')) as wins
        from public.profiles p
        where p.banned = false
          and (p_degree_level is null     or upper(p.degree_level) = upper(p_degree_level))
          and (p_specialization is null   or upper(p.specialization) = upper(p_specialization))
          and (p_department is null       or public.department_of(p.specialization) = upper(p_department))
    ),
    scored as (
        select
            b.*,
            case p_metric
                when 'collection' then case when t.n = 0 then 0 else round(100.0 * b.owned_count / t.n)::integer end
                when 'winrate'    then case when b.played = 0 then 0 else round(100.0 * b.wins / b.played)::integer end
                else b.level
            end as score,
            case p_metric
                when 'collection' then b.owned_count
                when 'winrate'    then b.wins
                else b.experience
            end as value,
            row_number() over (
                order by
                    case p_metric
                        when 'collection' then case when t.n = 0 then 0 else round(100.0 * b.owned_count / t.n)::integer end
                        when 'winrate'    then case when b.played = 0 then 0 else round(100.0 * b.wins / b.played)::integer end
                        else b.level
                    end desc,
                    case p_metric
                        when 'collection' then b.owned_count
                        when 'winrate'    then b.wins
                        else b.experience
                    end desc,
                    b.display_name asc
            ) as rn
        from base b
        cross join tot t
    )
    select jsonb_build_object(
        'rows', coalesce((
            select jsonb_agg(jsonb_build_object(
                'rank', s.rn, 'playerId', s.id, 'displayName', s.display_name,
                'avatar', s.avatar, 'degreeLevel', s.degree_level,
                'specialization', s.specialization, 'score', s.score, 'value', s.value)
            order by s.rn)
            from scored s
            where s.rn <= least(greatest(p_limit, 1), 100)
        ), '[]'::jsonb),
        'myRank', (select s.rn from scored s where s.id = auth.uid()),
        'total', (select count(*) from scored)
    );
$$;

revoke all on function public.leaderboard_full(text, text, text, text, integer) from public;
grant execute on function public.leaderboard_full(text, text, text, text, integer) to authenticated;
grant execute on function public.leaderboard_full(text, text, text, text, integer) to anon;
grant execute on function public.leaderboard_full(text, text, text, text, integer) to service_role;

-- ---------------------------------------------------------------
-- search_players: GET /api/v1/players/search port (PlayerController.search).
-- Matches display name first (top 10), then email (top 10), deduped, ordered
-- by name. Output never includes the email column (PlayerSummaryDto fields
-- only); SECURITY DEFINER so the search crosses RLS like the legacy endpoint.
-- ---------------------------------------------------------------
create or replace function public.search_players(p_query text default null)
returns table (
    id             uuid,
    display_name   text,
    avatar         text,
    student_id     text,
    degree_level   text,
    specialization text
)
language sql
security definer
set search_path = public
stable
as $$
    select p.id, p.display_name, p.avatar, p.student_id, p.degree_level, p.specialization
    from public.profiles p
    where p.banned = false
      and ((p_query is null or p_query = '')
           or p.display_name ilike '%' || p_query || '%'
           or p.email ilike '%' || p_query || '%')
    order by
        case when p_query is not null and p_query <> '' and p.display_name ilike '%' || p_query || '%' then 0 else 1 end,
        p.display_name asc
    limit 20;
$$;

revoke all on function public.search_players(text) from public;
grant execute on function public.search_players(text) to authenticated;
grant execute on function public.search_players(text) to service_role;

-- ---------------------------------------------------------------
-- player_unique_cards: GET /api/v1/players/{id}/unique-cards port
-- (PlayerController.uniqueCards → UniqueCardDto). SECURITY DEFINER because RLS
-- only shows own uniques (plus pending-trade cards) and TradePage legitimately
-- browses a partner's collection before offering.
-- ---------------------------------------------------------------
create or replace function public.player_unique_cards(p_player uuid)
returns table (
    physical_uuid uuid,
    card_id       uuid,
    forge_name    text,
    set_code      text,
    rarity        text,
    image_url     text,
    serial_number integer,
    claimed_at    timestamptz,
    history       text
)
language sql
security definer
set search_path = public
stable
as $$
    select uc.physical_uuid, uc.card_id, c.forge_name, c.set_code, c.rarity, c.image_url,
           uc.serial_number, uc.claimed_at, uc.history
    from public.unique_cards uc
    join public.cards c on c.id = uc.card_id
    where uc.owner_id = p_player
    order by c.forge_name asc, uc.serial_number asc;
$$;

revoke all on function public.player_unique_cards(uuid) from public;
grant execute on function public.player_unique_cards(uuid) to authenticated;
grant execute on function public.player_unique_cards(uuid) to service_role;

-- ---------------------------------------------------------------
-- list_my_trades: GET /trades/incoming + /trades/outgoing + GET /trades/{id}
-- port (TradeService). Returns full TradeDto JSON (sender/receiver players +
-- offered/requested cards). 'INCOMING'/'OUTGOING' lazily expire pending trades
-- whose 24h TTL passed (matching expireAll); 'ALL' is the read-only view used
-- by get-trade after an accept/decline/cancel so the UI refreshes one row.
-- ---------------------------------------------------------------
create or replace function public.list_my_trades(p_direction text default 'ALL')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid    uuid := auth.uid();
    v_result jsonb;
    v_ids    uuid[];
begin
    if v_uid is null then
        return '[]'::jsonb;
    end if;

    if p_direction in ('INCOMING', 'OUTGOING') then
        -- capture the pending set first, then lazily expire (separate statement
        -- so the returned payload sees the EXPIRED status, matching expireAll)
        select array_agg(t.id) into v_ids
        from public.trades t
        where t.status = 'PENDING'
          and (
               (p_direction = 'INCOMING' and t.receiver_id = v_uid)
            or (p_direction = 'OUTGOING' and t.sender_id = v_uid)
          );

        if v_ids is not null then
            update public.trades
               set status = 'EXPIRED', resolved_at = now()
             where id = any(v_ids) and expires_at < now();
        end if;

        select coalesce(jsonb_agg(payload order by created_at desc), '[]'::jsonb)
        into v_result
        from (
            select jsonb_build_object(
                'id', t.id,
                'status', t.status,
                'sender', jsonb_build_object(
                    'id', sp.id, 'displayName', sp.display_name, 'avatar', sp.avatar,
                    'studentId', sp.student_id, 'degreeLevel', sp.degree_level,
                    'specialization', sp.specialization),
                'receiver', jsonb_build_object(
                    'id', rp.id, 'displayName', rp.display_name, 'avatar', rp.avatar,
                    'studentId', rp.student_id, 'degreeLevel', rp.degree_level,
                    'specialization', rp.specialization),
                'offered', coalesce((
                    select jsonb_agg(jsonb_build_object(
                        'physicalUuid', tc.physical_uuid, 'cardId', c.id,
                        'forgeName', c.forge_name, 'setCode', c.set_code,
                        'rarity', c.rarity, 'imageUrl', c.image_url,
                        'serialNumber', uc.serial_number)
                    order by c.forge_name)
                    from public.trade_cards tc
                    join public.unique_cards uc on uc.physical_uuid = tc.physical_uuid
                    join public.cards c on c.id = uc.card_id
                    where tc.trade_id = t.id and tc.side = 'OFFERED'), '[]'::jsonb),
                'requested', coalesce((
                    select jsonb_agg(jsonb_build_object(
                        'physicalUuid', tc.physical_uuid, 'cardId', c.id,
                        'forgeName', c.forge_name, 'setCode', c.set_code,
                        'rarity', c.rarity, 'imageUrl', c.image_url,
                        'serialNumber', uc.serial_number)
                    order by c.forge_name)
                    from public.trade_cards tc
                    join public.unique_cards uc on uc.physical_uuid = tc.physical_uuid
                    join public.cards c on c.id = uc.card_id
                    where tc.trade_id = t.id and tc.side = 'REQUESTED'), '[]'::jsonb),
                'createdAt', t.created_at,
                'resolvedAt', t.resolved_at,
                'expiresAt', t.expires_at
            ) as payload, t.created_at as created_at
            from public.trades t
            join public.profiles sp on sp.id = t.sender_id
            join public.profiles rp on rp.id = t.receiver_id
            where t.id = any(coalesce(v_ids, '{}'::uuid[]))
        ) dto;
        return v_result;
    end if;

    -- 'ALL' (default): every trade involving the caller, no state mutation.
    select coalesce(jsonb_agg(payload order by created_at desc), '[]'::jsonb)
    into v_result
    from (
        select jsonb_build_object(
            'id', t.id,
            'status', t.status,
            'sender', jsonb_build_object(
                'id', sp.id, 'displayName', sp.display_name, 'avatar', sp.avatar,
                'studentId', sp.student_id, 'degreeLevel', sp.degree_level,
                'specialization', sp.specialization),
            'receiver', jsonb_build_object(
                'id', rp.id, 'displayName', rp.display_name, 'avatar', rp.avatar,
                'studentId', rp.student_id, 'degreeLevel', rp.degree_level,
                'specialization', rp.specialization),
            'offered', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'physicalUuid', tc.physical_uuid, 'cardId', c.id,
                    'forgeName', c.forge_name, 'setCode', c.set_code,
                    'rarity', c.rarity, 'imageUrl', c.image_url,
                    'serialNumber', uc.serial_number)
                order by c.forge_name)
                from public.trade_cards tc
                join public.unique_cards uc on uc.physical_uuid = tc.physical_uuid
                join public.cards c on c.id = uc.card_id
                where tc.trade_id = t.id and tc.side = 'OFFERED'), '[]'::jsonb),
            'requested', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'physicalUuid', tc.physical_uuid, 'cardId', c.id,
                    'forgeName', c.forge_name, 'setCode', c.set_code,
                    'rarity', c.rarity, 'imageUrl', c.image_url,
                    'serialNumber', uc.serial_number)
                order by c.forge_name)
                from public.trade_cards tc
                join public.unique_cards uc on uc.physical_uuid = tc.physical_uuid
                join public.cards c on c.id = uc.card_id
                where tc.trade_id = t.id and tc.side = 'REQUESTED'), '[]'::jsonb),
            'createdAt', t.created_at,
            'resolvedAt', t.resolved_at,
            'expiresAt', t.expires_at
        ) as payload, t.created_at as created_at
        from public.trades t
        join public.profiles sp on sp.id = t.sender_id
        join public.profiles rp on rp.id = t.receiver_id
        where t.sender_id = v_uid or t.receiver_id = v_uid
    ) dto;
    return v_result;
end;
$$;

revoke all on function public.list_my_trades(text) from public;
grant execute on function public.list_my_trades(text) to authenticated;
grant execute on function public.list_my_trades(text) to service_role;

-- ---------------------------------------------------------------
-- validate_deck_spec: POST /decks/validate port (DeckValidationService.validate
-- without an event gate; battle-time event gating stays on validate_deck).
-- Accepts {formatCode, commanderCardId, cards:[{cardId,quantity}]} and returns
-- jsonb { valid, problems: [{code, message, cardId}] } with the exact problem
-- vocabulary of the Java service.
-- ---------------------------------------------------------------
create or replace function public.validate_deck_spec(
    p_format_code  text,
    p_commander    uuid,
    p_cards        jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid       uuid := auth.uid();
    f           public.formats%rowtype;
    v_problems  jsonb := '[]'::jsonb;
    e           record;
    v_card      record;
    v_owned_qty bigint;
    v_owns      boolean;
    v_leg       text;
    v_basic     boolean;
    v_total     integer := 0;
    v_cmdr      record;
    v_cmdr_colors text;
    v_colors    text;
    v_ch        text;
    v_entry     record;
    v_color_ok  boolean;
begin
    select * into f from public.formats where code = p_format_code;
    if not found then
        return jsonb_build_object('valid', false, 'problems', jsonb_build_array(
            jsonb_build_object('code', 'UNKNOWN_FORMAT', 'message', 'Unknown format: ' || p_format_code, 'cardId', null)
        ));
    end if;

    -- accumulate ownership / copies / legality problems, remember the card map
    for e in
        select (elem->>'cardId')::uuid as card_id,
               sum(coalesce((elem->>'quantity')::integer, 0))::integer as qty
        from jsonb_array_elements(coalesce(p_cards, '[]'::jsonb)) as elem
        where elem->>'cardId' is not null
        group by 1
    loop
        v_card := null;
        select c.id, c.forge_name, c.ownership_type, c.colors, c.types, c.commander_eligible
          into v_card
          from public.cards c where c.id = e.card_id;
        if not found then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'UNKNOWN_CARD', 'message', 'Unknown card: ' || e.card_id, 'cardId', e.card_id));
            continue;
        end if;

        v_owned_qty := case v_card.ownership_type
            when 'UNLIMITED' then 2147483647
            when 'UNLOCK' then (select count(*) from public.player_unlocks where player_id = v_uid and card_id = e.card_id)
            else (select count(*) from public.unique_cards where owner_id = v_uid and card_id = e.card_id)
        end;
        v_owns := v_owned_qty > 0;

        if not v_owns then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NOT_OWNED', 'message', 'You do not own: ' || v_card.forge_name, 'cardId', e.card_id));
        end if;
        if v_owned_qty < e.qty then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NOT_ENOUGH_COPIES',
                'message', 'Only ' || v_owned_qty || ' owned of: ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        select legality into v_leg from public.card_legalities
         where card_id = e.card_id and format_id = f.id;
        if v_leg = 'BANNED' then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'BANNED', 'message', 'Banned in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        elsif v_leg = 'RESTRICTED' and e.qty > 1 then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'RESTRICTED', 'message', 'Restricted to 1 copy in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        v_basic := v_card.types is not null and v_card.types like '%Basic Land%';
        if not (f.basics_unlimited and v_basic) and e.qty > f.max_copies then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'TOO_MANY_COPIES', 'message',
                'Max ' || f.max_copies || ' copies in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        v_total := v_total + e.qty;
    end loop;

    if v_total < f.min_deck_size then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
            'code', 'TOO_FEW_CARDS', 'message',
            'Minimum ' || f.min_deck_size || ' cards, got ' || v_total, 'cardId', null));
    end if;
    if f.max_deck_size is not null and v_total > f.max_deck_size then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
            'code', 'TOO_MANY_CARDS', 'message',
            'Maximum ' || f.max_deck_size || ' cards, got ' || v_total, 'cardId', null));
    end if;

    if f.commander_required then
        if p_commander is null then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NO_COMMANDER', 'message', 'A commander is required.', 'cardId', null));
        else
            v_cmdr := null;
            select c.id, c.forge_name, c.colors, c.commander_eligible
              into v_cmdr
              from public.cards c where c.id = p_commander;
            if not found then
                v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                    'code', 'UNKNOWN_COMMANDER', 'message', 'Unknown commander card', 'cardId', p_commander));
            else
                v_owned_qty := (select case ownership_type
                    when 'UNLIMITED' then 2147483647
                    when 'UNLOCK' then (select count(*) from public.player_unlocks where player_id = v_uid and card_id = v_cmdr.id)
                    else (select count(*) from public.unique_cards where owner_id = v_uid and card_id = v_cmdr.id)
                end from public.cards where id = v_cmdr.id);
                if not (v_owned_qty > 0) then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'COMMANDER_NOT_OWNED', 'message', 'You do not own: ' || v_cmdr.forge_name,
                        'cardId', v_cmdr.id));
                end if;
                if not v_cmdr.commander_eligible then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'NOT_LEGENDARY', 'message', v_cmdr.forge_name || ' cannot be a commander.',
                        'cardId', v_cmdr.id));
                end if;
                select legality into v_leg from public.card_legalities
                 where card_id = v_cmdr.id and format_id = f.id;
                if v_leg = 'BANNED' then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'BANNED_COMMANDER', 'message', v_cmdr.forge_name || ' is banned as commander.',
                        'cardId', v_cmdr.id));
                end if;

                v_cmdr_colors := coalesce(v_cmdr.colors, '');

                -- color identity: every requested card's colors must be a
                -- subset of the commander's (DeckValidationService.isColorSubset)
                for v_entry in
                    select c.id, c.forge_name, c.colors
                    from public.cards c
                    where c.id in (
                        select (elem->>'cardId')::uuid
                        from jsonb_array_elements(coalesce(p_cards, '[]'::jsonb)) elem
                        where elem->>'cardId' is not null
                        union
                        select p_commander
                    )
                loop
                    v_colors := coalesce(v_entry.colors, '');
                    v_color_ok := true;
                    for v_ch in select * from unnest(string_to_array(v_colors, '')) loop
                        if position(v_ch in v_cmdr_colors) = 0 then
                            v_color_ok := false;
                            exit;
                        end if;
                    end loop;
                    if not v_color_ok then
                        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                            'code', 'COLOR_IDENTITY', 'message',
                            v_entry.forge_name || ' (colors ' || v_colors || ') is outside '
                                || v_cmdr.forge_name || '''s color identity (' || v_cmdr_colors || ').',
                            'cardId', v_entry.id));
                    end if;
                end loop;
            end if;
        end if;
    end if;

    return jsonb_build_object('valid', (v_problems = '[]'::jsonb), 'problems', v_problems);
end;
$$;

revoke all on function public.validate_deck_spec(text, uuid, jsonb) from public;
grant execute on function public.validate_deck_spec(text, uuid, jsonb) to authenticated;
grant execute on function public.validate_deck_spec(text, uuid, jsonb) to service_role;

-- ******************** FILE: migrations/20260924000012_analytics_rpc_alignment.sql ********************
-- Campus Forge → Supabase
-- Migration 12: align the analytics read RPCs with the retired backend's
-- AnalyticsService (the migration 07 versions drifted).
--
--   popular_decks  : aggregate by deck NAME across matches that are not
--                    PENDING (counts deck1 + deck2), like
--                    AnalyticsService.popularDecks — not by deck id.
--   active_buildings: count every claim with a non-blank building, whether or
--                    not it was ever claimed, like
--                    AnalyticsService.activeBuildings.
--
-- The OUT-column sets change, so CREATE OR REPLACE is not enough: drop first.
-- Idempotent: safe to paste into the hosted SQL Editor more than once.

drop function if exists public.popular_decks(integer);
create function public.popular_decks(p_limit integer default 10)
returns table (
    deck_name  text,
    play_count bigint
)
language sql
stable
as $$
    select d.name as deck_name, count(*) as play_count
    from public.matches m
    join public.decks d on d.id = m.deck1_id or d.id = m.deck2_id
    where m.status <> 'PENDING'
    group by d.name
    order by play_count desc, d.name asc
    limit least(greatest(p_limit, 1), 100);
$$;

grant execute on function public.popular_decks(integer) to authenticated;
grant execute on function public.popular_decks(integer) to anon;

drop function if exists public.active_buildings(integer);
create function public.active_buildings(p_limit integer default 10)
returns table (
    building text,
    claims   bigint
)
language sql
stable
as $$
    select btrim(building) as building, count(*) as claims
    from public.claims
    where building is not null and btrim(building) <> ''
    group by btrim(building)
    order by claims desc, btrim(building) asc
    limit least(greatest(p_limit, 1), 100);
$$;

grant execute on function public.active_buildings(integer) to authenticated;
grant execute on function public.active_buildings(integer) to anon;

-- ******************** FILE: migrations/20260924000013_security_hardening.sql ********************
-- Campus Forge → Supabase
-- Migration 13: production security hardening + durable game history.
--
-- Fixes (all verified against a Supabase-shaped Postgres before shipping):
--   * Function privileges. Supabase's default privileges GRANT EXECUTE on every
--     new public function to anon + authenticated *directly*, so the
--     `revoke ... from public` lines in 06–11 never took effect: apply_claim,
--     record_match_result, add_feed_entry, ensure_print_claim, … were callable
--     by anyone with the publishable key (e.g. unlock every card for any player,
--     since print cores are derivable from public card ids). Now: revoke all,
--     then allow-list exactly what the PWA calls.
--   * profiles: a player could UPDATE their own role/experience/level/banned.
--     A trigger now pins those columns unless the caller is an admin or a
--     trusted server path (service role / definer functions).
--   * Direct-write RLS holes: players could insert their own unlocks,
--     discoveries and achievements, and insert/update trades + trade_cards
--     directly (skipping create_trade validation, or flipping status to
--     ACCEPTED). Writes now go only through the definer RPCs.
--   * Trade RPCs trusted auth.uid() without a NULL check; a caller with no
--     user (anon/service) slipped past the participant checks.
--   * my_profile_stats(p_player) returned any player's email to anyone.
--   * popular_decks / active_buildings ran as invoker, so RLS silently limited
--     the "global" analytics to the caller's own rows.
--   * validate_deck (battle-time) skipped the deck-size check when the deck had
--     no cards, ignored copy counts, and checked bans in every format.
--   * Banned players can no longer claim or trade.
--
-- Adds:
--   * public.game_log: append-only history (claims, trades, match results,
--     starter grants, admin spawns) — activity_feed is a 50-row UI ring, this
--     is the durable record. Owner/admin readable; written only server-side.
--   * trades on the supabase_realtime publication (live incoming offers).
--
-- Idempotent: safe to paste into the SQL Editor more than once.

-- ---------------------------------------------------------------
-- game_log: durable, append-only event history
-- ---------------------------------------------------------------
create table if not exists public.game_log (
    id         bigint generated always as identity primary key,
    kind       text not null check (kind in ('CLAIM', 'TRADE', 'MATCH', 'STARTER', 'SPAWN')),
    player_id  uuid references public.profiles (id) on delete set null,
    card_id    uuid references public.cards (id) on delete set null,
    ref_id     uuid,
    xp         bigint not null default 0,
    detail     jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now()
);

create index if not exists idx_game_log_player_created on public.game_log (player_id, created_at desc);
create index if not exists idx_game_log_kind_created on public.game_log (kind, created_at desc);

alter table public.game_log enable row level security;

drop policy if exists game_log_select_own on public.game_log;
create policy game_log_select_own on public.game_log for select
to authenticated
using (player_id = auth.uid() or public.is_admin());

-- no insert/update/delete policies: only definer functions + service role write.
revoke insert, update, delete, truncate on public.game_log from anon, authenticated;

-- ---------------------------------------------------------------
-- assert_active_player: the caller must be a signed-in, non-banned player.
-- ---------------------------------------------------------------
create or replace function public.assert_active_player(p_player uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_banned boolean;
begin
    if p_player is null then
        raise exception 'Not authenticated' using errcode = 'CF401';
    end if;
    select banned into v_banned from public.profiles where id = p_player;
    if not found then
        raise exception 'Player not found' using errcode = 'CF404';
    end if;
    if v_banned then
        raise exception 'This account is banned' using errcode = 'CF403';
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- profiles: players may only edit their own presentation/cohort fields.
-- current_user is 'authenticated'/'anon' for PostgREST requests and the
-- function owner inside SECURITY DEFINER functions, so server paths
-- (apply_claim XP, record_match_result, admin tooling via service role)
-- are unaffected.
-- ---------------------------------------------------------------
create or replace function public.guard_profile_update()
returns trigger
language plpgsql
as $$
begin
    if current_user in ('anon', 'authenticated') and not public.is_admin() then
        if new.id is distinct from old.id
           or new.email is distinct from old.email
           or new.role is distinct from old.role
           or new.experience is distinct from old.experience
           or new.banned is distinct from old.banned
           or new.banned_at is distinct from old.banned_at
           or new.created is distinct from old.created then
            raise exception 'Players may only edit display name, avatar, student id, cohort and onboarding fields'
                using errcode = '42501';
        end if;
    end if;
    -- level is always derived (trg_profiles_sync_level only fires on experience changes)
    new.level := public.compute_level(new.experience);
    return new;
end;
$$;

drop trigger if exists trg_profiles_guard on public.profiles;
create trigger trg_profiles_guard
before update on public.profiles
for each row execute function public.guard_profile_update();

do $$
begin
    if not exists (select 1 from pg_constraint where conname = 'chk_profiles_display_name') then
        alter table public.profiles
            add constraint chk_profiles_display_name
            check (char_length(btrim(display_name)) between 1 and 40) not valid;
    end if;
    if not exists (select 1 from pg_constraint where conname = 'chk_deck_cards_quantity') then
        alter table public.deck_cards
            add constraint chk_deck_cards_quantity check (quantity between 1 and 250) not valid;
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- RLS: remove direct-write policies that bypass the game rules.
-- ---------------------------------------------------------------
drop policy if exists player_unlocks_insert_own on public.player_unlocks;
drop policy if exists player_unlocks_delete_own on public.player_unlocks;   -- delete + rescan = XP farm
drop policy if exists discoveries_insert_own on public.discoveries;
drop policy if exists discoveries_update_own on public.discoveries;
drop policy if exists player_achievements_insert_own on public.player_achievements;
drop policy if exists trades_insert_sender on public.trades;
drop policy if exists trades_update_party on public.trades;
drop policy if exists trade_cards_insert_party on public.trade_cards;
drop policy if exists trade_cards_delete_party on public.trade_cards;

-- the feed carries player names; keep it behind sign-in (Realtime included).
drop policy if exists activity_feed_select_all on public.activity_feed;
drop policy if exists activity_feed_select_auth on public.activity_feed;
create policy activity_feed_select_auth on public.activity_feed for select
to authenticated
using (true);

-- ---------------------------------------------------------------
-- apply_claim: + banned check, + game_log row. Otherwise unchanged (06).
-- ---------------------------------------------------------------
create or replace function public.apply_claim(p_core text, p_player uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    c          public.claims%rowtype;
    v_card     public.cards%rowtype;
    v_count    bigint;
    v_owns     boolean;
    v_unlocked boolean := false;
    v_xp       bigint := 0;
    v_phys     uuid := null;
    v_serial   integer;
    v_bonus    numeric := 1.00;
begin
    perform public.assert_active_player(p_player);

    select * into c from public.claims where token_core = p_core for update;
    if not found then
        raise exception 'Claim token not found: %', p_core using errcode = 'CF404';
    end if;

    select * into v_card from public.cards where id = c.card_id;
    if not found then
        raise exception 'unknown card' using errcode = 'CF404';
    end if;

    if c.status = 'REVOKED' then
        raise exception 'Claim token has been revoked' using errcode = 'CF410';
    end if;
    if c.expires_at is not null and c.expires_at < now() then
        update public.claims set status = 'EXPIRED' where id = c.id;
        raise exception 'Claim token has expired' using errcode = 'CF410';
    end if;
    if v_card.ownership_type = 'UNIQUE' and c.claimed_by is not null then
        raise exception 'This unique card has already been claimed' using errcode = 'CF409';
    end if;
    if c.status <> 'ACTIVE' then
        raise exception 'Claim token is no longer active' using errcode = 'CF410';
    end if;

    insert into public.discoveries (id, player_id, card_id, count, last_discovered)
    values (gen_random_uuid(), p_player, c.card_id, 1, now())
    on conflict on constraint uk_discoveries_player_card do update
    set count = public.discoveries.count + 1,
        last_discovered = now();

    select d.count into v_count
      from public.discoveries d
     where d.player_id = p_player and d.card_id = c.card_id;

    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.active = true and e.start_time <= now() and e.end_time >= now()
     order by e.start_time
     limit 1;
    if not found then
        v_bonus := 1.00;
    end if;

    v_owns := (v_card.ownership_type = 'UNLIMITED')
           or (v_card.ownership_type = 'UNLOCK'
               and exists (select 1 from public.player_unlocks ul
                            where ul.player_id = p_player and ul.card_id = v_card.id))
           or (v_card.ownership_type = 'UNIQUE'
               and exists (select 1 from public.unique_cards uq
                            where uq.owner_id = p_player and uq.card_id = v_card.id));

    if not v_owns then
        if v_card.ownership_type = 'UNLOCK' then
            insert into public.player_unlocks (id, player_id, card_id, unlocked_at)
            values (gen_random_uuid(), p_player, v_card.id, now())
            on conflict on constraint uk_player_unlocks_player_card do nothing;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        elsif v_card.ownership_type = 'UNIQUE' then
            select coalesce(max(uq.serial_number), 0) + 1 into v_serial
              from public.unique_cards uq where uq.card_id = v_card.id;
            v_phys := public.unique_physical_uuid(c.token_core);
            insert into public.unique_cards (physical_uuid, owner_id, card_id, serial_number, history)
            values (v_phys, p_player, c.card_id, v_serial, 'claimed via discovery')
            on conflict (physical_uuid) do nothing;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        end if;
    end if;

    if v_unlocked then
        update public.profiles set experience = experience + v_xp where id = p_player;
        perform public.add_feed_entry('DISCOVERY', 'discovered ' || v_card.forge_name, p_player, v_card.id);
    else
        perform public.add_feed_entry('DISCOVERY', 'scanned ' || v_card.forge_name, p_player, v_card.id);
    end if;

    if v_card.ownership_type = 'UNIQUE' then
        update public.claims set status = 'CLAIMED', claimed_by = p_player, claimed_at = now()
         where id = c.id;
    else
        update public.claims set claimed_by = p_player, claimed_at = now() where id = c.id;
    end if;

    insert into public.game_log (kind, player_id, card_id, ref_id, xp, detail)
    values ('CLAIM', p_player, v_card.id, c.id, v_xp, jsonb_build_object(
        'unlocked', v_unlocked,
        'building', c.building,
        'eventId', c.event_id,
        'bonus', v_bonus,
        'discoveryCount', v_count,
        'physicalUuid', v_phys));

    return jsonb_build_object(
        'card', jsonb_build_object(
            'id', v_card.id,
            'oracleId', v_card.oracle_id,
            'forgeName', v_card.forge_name,
            'rarity', v_card.rarity,
            'ownershipType', v_card.ownership_type,
            'setCode', v_card.set_code,
            'manaValue', v_card.mana_value,
            'types', v_card.types,
            'colors', v_card.colors,
            'imageUrl', v_card.image_url,
            'discoverable', v_card.discoverable,
            'spawnRegion', v_card.spawn_region,
            'weight', v_card.weight,
            'commanderEligible', v_card.commander_eligible
        ),
        'unlocked', v_unlocked,
        'alreadyOwned', (not v_unlocked),
        'discoveryCount', v_count,
        'experienceAwarded', v_xp,
        'token', c.token,
        'building', c.building,
        'physicalUuid', v_phys
    );
end;
$$;

-- ---------------------------------------------------------------
-- accept_trade: + NULL-actor/banned guard, + game_log rows.
-- ---------------------------------------------------------------
create or replace function public.accept_trade(p_trade uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    t               public.trades%rowtype;
    v_card_uuid     uuid;
    v_side          text;
    v_from_name     text;
    v_to_name       text;
    v_now           timestamptz := now();
    v_sender_name   text;
    v_receiver_name text;
    v_actor         uuid := auth.uid();
    v_offered       jsonb;
    v_requested     jsonb;
begin
    perform public.assert_active_player(v_actor);

    select * into t from public.trades where id = p_trade for update;
    if not found or (v_actor <> t.sender_id and v_actor <> t.receiver_id) then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if v_actor = t.sender_id then
        raise exception 'Only the receiver can perform this action on the trade' using errcode = 'CF403';
    end if;
    if t.status <> 'PENDING' then
        raise exception 'Trade is already %', lower(t.status) using errcode = 'CF409';
    end if;
    if t.expires_at < v_now then
        update public.trades set status = 'EXPIRED', resolved_at = v_now where id = t.id;
        raise exception 'Trade has expired' using errcode = 'CF410';
    end if;

    select display_name into v_sender_name   from public.profiles where id = t.sender_id;
    select display_name into v_receiver_name from public.profiles where id = t.receiver_id;

    -- lock every involved card in sorted-UUID order (deadlock avoidance)
    for v_card_uuid in
        select tc.physical_uuid from public.trade_cards tc
         where tc.trade_id = t.id order by tc.physical_uuid
    loop
        perform 1 from public.unique_cards where physical_uuid = v_card_uuid for update;
    end loop;

    -- ownership re-verification
    if exists (
        select 1
          from public.trade_cards tc
          left join public.unique_cards uc on uc.physical_uuid = tc.physical_uuid
         where tc.trade_id = t.id
           and (uc.physical_uuid is null
                or (tc.side = 'OFFERED'   and uc.owner_id <> t.sender_id)
                or (tc.side = 'REQUESTED' and uc.owner_id <> t.receiver_id))
    ) then
        raise exception 'Ownership changed; trade no longer valid' using errcode = 'CF409';
    end if;

    -- swap owners + append history (display names, "\n"-joined)
    for v_card_uuid, v_side in
        select tc.physical_uuid, tc.side from public.trade_cards tc
         where tc.trade_id = t.id order by tc.physical_uuid
    loop
        if v_side = 'OFFERED' then
            v_from_name := v_sender_name;
            v_to_name   := v_receiver_name;
        else
            v_from_name := v_receiver_name;
            v_to_name   := v_sender_name;
        end if;
        update public.unique_cards
           set owner_id = case when v_side = 'OFFERED' then t.receiver_id else t.sender_id end,
               history = coalesce(nullif(history, ''), '')
                          || case when history is null or history = '' then '' else E'\n' end
                          || to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS') || ': '
                          || v_from_name || ' → ' || v_to_name || ' via trade ' || t.id
         where physical_uuid = v_card_uuid;
    end loop;

    update public.trades set status = 'ACCEPTED', resolved_at = v_now where id = t.id;

    select coalesce(jsonb_agg(physical_uuid) filter (where side = 'OFFERED'), '[]'::jsonb),
           coalesce(jsonb_agg(physical_uuid) filter (where side = 'REQUESTED'), '[]'::jsonb)
      into v_offered, v_requested
      from public.trade_cards where trade_id = t.id;

    insert into public.game_log (kind, player_id, ref_id, detail) values
        ('TRADE', t.sender_id,   t.id, jsonb_build_object('role', 'SENDER',   'partner', t.receiver_id, 'gave', v_offered,   'got', v_requested)),
        ('TRADE', t.receiver_id, t.id, jsonb_build_object('role', 'RECEIVER', 'partner', t.sender_id,   'gave', v_requested, 'got', v_offered));

    perform public.add_feed_entry('TRADE', 'traded unique cards with ' || v_receiver_name, t.sender_id);

    return 'ACCEPTED';
end;
$$;

-- ---------------------------------------------------------------
-- resolve_trade: + NULL-actor guard (banned players may still back out).
-- ---------------------------------------------------------------
create or replace function public.resolve_trade(p_trade uuid, p_action text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    t       public.trades%rowtype;
    v_now   timestamptz := now();
    v_actor uuid := auth.uid();
begin
    if v_actor is null then
        raise exception 'Not authenticated' using errcode = 'CF401';
    end if;
    if p_action not in ('DECLINED', 'CANCELLED') then
        raise exception 'unknown action %', p_action using errcode = 'CF400';
    end if;

    select * into t from public.trades where id = p_trade for update;
    if not found or (v_actor <> t.sender_id and v_actor <> t.receiver_id) then
        raise exception 'Trade not found: %', p_trade using errcode = 'CF404';
    end if;
    if p_action = 'DECLINED' and v_actor = t.sender_id then
        raise exception 'Only the receiver can perform this action on the trade' using errcode = 'CF403';
    end if;
    if p_action = 'CANCELLED' and v_actor = t.receiver_id then
        raise exception 'Only the sender can perform this action on the trade' using errcode = 'CF403';
    end if;
    if t.status <> 'PENDING' then
        raise exception 'Trade is already %', lower(t.status) using errcode = 'CF409';
    end if;
    if t.expires_at < v_now then
        update public.trades set status = 'EXPIRED', resolved_at = v_now where id = t.id;
        raise exception 'Trade has expired' using errcode = 'CF410';
    end if;

    update public.trades set status = p_action, resolved_at = v_now where id = t.id;
    return p_action;
end;
$$;

-- ---------------------------------------------------------------
-- create_trade: + NULL-actor/banned guard, bundle size cap, banned receivers
-- are invisible (matches search_players).
-- ---------------------------------------------------------------
create or replace function public.create_trade(
    p_receiver uuid,
    p_offered uuid[],
    p_requested uuid[]
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_trade  uuid := gen_random_uuid();
    v_card   uuid;
    v_sender uuid := auth.uid();
    v_name   text;
begin
    perform public.assert_active_player(v_sender);

    if p_receiver = v_sender then
        raise exception 'You cannot trade with yourself' using errcode = 'CF400';
    end if;
    if not exists (select 1 from public.profiles where id = p_receiver and banned = false) then
        raise exception 'Receiver not found' using errcode = 'CF404';
    end if;
    if coalesce(array_length(p_offered, 1), 0) = 0 and coalesce(array_length(p_requested, 1), 0) = 0 then
        raise exception 'Empty trade' using errcode = 'CF400';
    end if;
    if coalesce(array_length(p_offered, 1), 0) > 20 or coalesce(array_length(p_requested, 1), 0) > 20 then
        raise exception 'At most 20 cards per side' using errcode = 'CF400';
    end if;

    if p_offered is not null
       and (select count(*) from unnest(p_offered) x) <> (select count(distinct x) from unnest(p_offered) x) then
        raise exception 'Duplicate offered card in bundle' using errcode = 'CF400';
    end if;
    if p_requested is not null
       and (select count(*) from unnest(p_requested) x) <> (select count(distinct x) from unnest(p_requested) x) then
        raise exception 'Duplicate requested card in bundle' using errcode = 'CF400';
    end if;
    if p_offered is not null and p_requested is not null
       and exists (select 1 from unnest(p_offered) o join unnest(p_requested) r on r = o) then
        raise exception 'A card cannot be both offered and requested' using errcode = 'CF400';
    end if;

    insert into public.trades (id, sender_id, receiver_id, status)
    values (v_trade, v_sender, p_receiver, 'PENDING');

    if p_offered is not null then
        foreach v_card in array p_offered loop
            select c.forge_name into v_name from public.cards c
              join public.unique_cards uq on uq.card_id = c.id
             where uq.physical_uuid = v_card;
            if not found then
                raise exception 'Offered unique card not found: %', v_card using errcode = 'CF404';
            end if;
            if not exists (select 1 from public.unique_cards where physical_uuid = v_card and owner_id = v_sender) then
                raise exception 'You do not own offered card: %', v_name using errcode = 'CF400';
            end if;
            insert into public.trade_cards (id, trade_id, side, physical_uuid)
            values (gen_random_uuid(), v_trade, 'OFFERED', v_card);
        end loop;
    end if;

    if p_requested is not null then
        foreach v_card in array p_requested loop
            select c.forge_name into v_name from public.cards c
              join public.unique_cards uq on uq.card_id = c.id
             where uq.physical_uuid = v_card;
            if not found then
                raise exception 'Requested unique card not found: %', v_card using errcode = 'CF404';
            end if;
            if not exists (select 1 from public.unique_cards where physical_uuid = v_card and owner_id = p_receiver) then
                raise exception 'Receiver does not own requested card: %', v_name using errcode = 'CF400';
            end if;
            insert into public.trade_cards (id, trade_id, side, physical_uuid)
            values (gen_random_uuid(), v_trade, 'REQUESTED', v_card);
        end loop;
    end if;

    return v_trade;
end;
$$;

-- ---------------------------------------------------------------
-- record_match_result (battle-engine, service role): + winner must be a
-- participant, + game_log rows for both players.
-- ---------------------------------------------------------------
create or replace function public.record_match_result(
    p_match     uuid,
    p_winner    uuid,
    p_win_cond  text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    m       public.matches%rowtype;
    v_xp    bigint := 50;
    v_bonus numeric := 1.00;
begin
    select * into m from public.matches where id = p_match for update;
    if not found then
        raise exception 'Match not found: %', p_match using errcode = 'CF404';
    end if;
    if m.status in ('FINISHED', 'CONCEDED') then
        return; -- idempotent
    end if;
    if p_winner is not null and p_winner is distinct from m.player1_id and p_winner is distinct from m.player2_id then
        raise exception 'Winner is not a participant of match %', p_match using errcode = 'CF400';
    end if;

    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.id = m.event_id
       and e.active = true and e.start_time <= now() and e.end_time >= now();
    if found then
        v_xp := round(50 * v_bonus)::bigint;
    end if;

    update public.matches
       set status = 'FINISHED',
           winner_id = p_winner,
           win_condition = coalesce(p_win_cond, m.win_condition),
           ended_at = now()
     where id = p_match;

    insert into public.game_log (kind, player_id, ref_id, xp, detail)
    select 'MATCH', pid, m.id,
           case when pid = p_winner then v_xp else 0 end,
           jsonb_build_object(
               'result', case when p_winner is null then 'DRAW' when pid = p_winner then 'WIN' else 'LOSS' end,
               'winCondition', coalesce(p_win_cond, m.win_condition),
               'opponent', case when pid = m.player1_id then m.player2_id else m.player1_id end,
               'eventId', m.event_id,
               'battleCode', m.battle_code)
      from unnest(array[m.player1_id, m.player2_id]) as pid
     where pid is not null;

    if p_winner is not null then
        update public.profiles set experience = experience + v_xp where id = p_winner;
        perform public.add_feed_entry('DISCOVERY', 'won a battle (+' || v_xp || ' XP)', p_winner);
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- validate_deck (battle-engine, service role): load the format first (an
-- empty deck previously skipped the size check), count owned copies like
-- validate_deck_spec, check bans in *this* format, enforce max size and
-- commander presence.
-- ---------------------------------------------------------------
create or replace function public.validate_deck(
    p_deck  uuid,
    p_event uuid default null
)
returns setof public.deck_problem
language plpgsql
security definer
set search_path = public
as $$
declare
    d         public.decks%rowtype;
    f         public.formats%rowtype;
    v_total   integer;
    v_allowed jsonb;
    e         record;
begin
    select * into d from public.decks where id = p_deck;
    if not found then
        return next row('ERROR', 'NOT_FOUND', 'deck not found')::public.deck_problem;
        return;
    end if;

    select * into f from public.formats where code = d.format_code;
    if not found then
        return next row('ERROR', 'UNKNOWN_FORMAT', format('unknown format %s', d.format_code))::public.deck_problem;
        return;
    end if;

    if p_event is not null then
        select allowed_sets_json::jsonb into v_allowed from public.events where id = p_event and active = true;
    end if;

    select coalesce(sum(dc.quantity), 0)::integer into v_total
      from public.deck_cards dc where dc.deck_id = p_deck;

    for e in
        select c.id, c.forge_name, c.set_code, dc.quantity,
               coalesce(c.types ilike '%Basic%', false) as basic,
               case c.ownership_type
                   when 'UNLIMITED' then 2147483647
                   when 'UNLOCK' then (select count(*) from public.player_unlocks u where u.player_id = d.player_id and u.card_id = c.id)
                   else (select count(*) from public.unique_cards uc where uc.owner_id = d.player_id and uc.card_id = c.id)
               end as owned_qty,
               exists (select 1 from public.card_legalities cl
                        where cl.card_id = c.id and cl.format_id = f.id and cl.legality = 'BANNED') as banned
          from public.deck_cards dc
          join public.cards c on c.id = dc.card_id
         where dc.deck_id = p_deck
    loop
        if e.owned_qty = 0 then
            return next row('ERROR', 'NOT_OWNED', format('%s is not owned by the player', e.forge_name))::public.deck_problem;
        elsif e.owned_qty < e.quantity then
            return next row('ERROR', 'NOT_ENOUGH_COPIES', format('only %s owned of %s', e.owned_qty, e.forge_name))::public.deck_problem;
        end if;
        if not (f.basics_unlimited and e.basic) and e.quantity > f.max_copies then
            return next row('ERROR', 'TOO_MANY_COPIES', format('%s exceeds max copies of %s', e.forge_name, f.max_copies))::public.deck_problem;
        end if;
        if e.banned then
            return next row('ERROR', 'BANNED_CARD', format('%s is banned in %s', e.forge_name, f.name))::public.deck_problem;
        end if;
        if v_allowed is not null and not e.basic
           and (e.set_code is null or not (e.set_code = any (select jsonb_array_elements_text(v_allowed)))) then
            return next row('ERROR', 'NOT_IN_EVENT', format('%s is not in the event allowed sets', e.forge_name))::public.deck_problem;
        end if;
    end loop;

    if v_total < f.min_deck_size then
        return next row('WARNING', 'NOT_ENOUGH_CARDS', format('deck has %s cards, requires %s', v_total, f.min_deck_size))::public.deck_problem;
    end if;
    if f.max_deck_size is not null and v_total > f.max_deck_size then
        return next row('ERROR', 'TOO_MANY_CARDS', format('deck has %s cards, maximum %s', v_total, f.max_deck_size))::public.deck_problem;
    end if;
    if f.commander_required and d.commander_card_id is null then
        return next row('ERROR', 'NO_COMMANDER', 'a commander is required')::public.deck_problem;
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- my_profile_stats: only your own stats unless admin/service role (it
-- returns the email address). Also fixes favoriteColors for multicolor
-- cards (string_to_array(x, '') does not split into characters).
-- ---------------------------------------------------------------
create or replace function public.my_profile_stats(p_player uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid       uuid := coalesce(p_player, auth.uid());
    v_exp       bigint;
    v_level     integer;
    v_xp_next   bigint;
    v_disc      bigint;
    v_owned     integer;
    v_total     integer;
    v_comp      integer;
    v_colors    text[];
    v_buildings text[];
    v_played    integer;
    v_wins      integer;
    v_losses    integer;
    v_rate      integer;
    v_player    jsonb;
    v_badges    jsonb;
begin
    if v_uid is null then
        return null;
    end if;
    if auth.uid() is not null and v_uid <> auth.uid() and not public.is_admin() then
        raise exception 'You can only view your own stats' using errcode = 'CF403';
    end if;

    select
        p.experience,
        public.compute_level(p.experience),
        jsonb_build_object(
            'id', p.id, 'email', p.email, 'displayName', p.display_name, 'role', p.role,
            'avatar', p.avatar, 'studentId', p.student_id,
            'degreeLevel', p.degree_level, 'specialization', p.specialization,
            'experience', p.experience, 'level', public.compute_level(p.experience)
        )
    into v_exp, v_level, v_player
      from public.profiles p where p.id = v_uid;
    if not found then
        return null;
    end if;

    v_xp_next := greatest(0, (v_level * 100) - v_exp);

    select coalesce(sum(count), 0) into v_disc
      from public.discoveries where player_id = v_uid;

    select count(*) into v_total from public.cards;
    select count(distinct c.id) into v_owned from public.cards c
     where c.ownership_type = 'UNLIMITED'
        or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
        or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id);
    v_comp := case when v_total = 0 then 0 else round(100.0 * v_owned / v_total)::integer end;

    -- favoriteColors: top 3 colors across owned cards, count desc then color asc
    select array_agg(ch order by cnt desc, ch asc) into v_colors
    from (
        select ch, count(*) as cnt
        from (
            select c.id, c.colors
            from public.cards c
            where (c.ownership_type = 'UNLIMITED'
                   or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
                   or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id))
              and coalesce(c.colors, '') <> ''
        ) owned,
        lateral unnest(string_to_array(upper(owned.colors), null)) as ch
        where ch in ('W', 'U', 'B', 'R', 'G')
        group by ch
        order by cnt desc, ch asc
        limit 3
    ) s;

    select array_agg(b order by b) into v_buildings
    from (
        select distinct btrim(building) as b
        from public.claims
        where claimed_by = v_uid and building is not null and btrim(building) <> ''
    ) s;

    select count(*) into v_played from public.matches
     where (player1_id = v_uid or player2_id = v_uid) and status in ('FINISHED', 'CONCEDED');
    select count(*) into v_wins from public.matches
     where winner_id = v_uid and status in ('FINISHED', 'CONCEDED');
    v_losses := v_played - v_wins;
    v_rate := case when v_played = 0 then 0 else round(100.0 * v_wins / v_played)::integer end;

    perform public.sweep_achievements(v_uid);
    select coalesce(jsonb_agg(jsonb_build_object('code', a.code, 'name', c.name, 'description', c.description)
                   order by a.unlocked_at), '[]'::jsonb)
      into v_badges
      from public.player_achievements a
      left join public.achievement_catalog() c on c.code = a.code
     where a.player_id = v_uid;

    return jsonb_build_object(
        'player', v_player,
        'experience', v_exp,
        'level', v_level,
        'experienceToNextLevel', v_xp_next,
        'collectionCompletionPercent', v_comp,
        'ownedCards', v_owned,
        'totalCards', v_total,
        'totalDiscoveries', v_disc,
        'favoriteColors', coalesce(v_colors, '{}'),
        'buildingsVisited', coalesce(v_buildings, '{}'),
        'battleStats', jsonb_build_object(
            'played', v_played, 'wins', v_wins, 'losses', v_losses, 'winRatePercent', v_rate
        ),
        'badges', v_badges
    );
end;
$$;

-- ---------------------------------------------------------------
-- Global analytics must see every row, not just the caller's.
-- ---------------------------------------------------------------
alter function public.popular_decks(integer) security definer set search_path = public;
alter function public.active_buildings(integer) security definer set search_path = public;

-- Unused migration-07 readers (superseded by leaderboard_full / my_profile_stats).
drop function if exists public.leaderboard(text, text, text, integer);
drop function if exists public.profile_stats(uuid);

-- ---------------------------------------------------------------
-- Realtime: live trade offers (RLS still applies to postgres_changes).
-- ---------------------------------------------------------------
do $$
begin
    if not exists (
        select 1 from pg_publication_tables
        where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'trades'
    ) then
        alter publication supabase_realtime add table public.trades;
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- Function privileges: deny by default, allow-list what clients call.
-- (Runs last so it covers every function defined above.)
-- ---------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;

-- used inside RLS policies / check constraints, so every API role needs them
grant execute on function
    public.is_admin(),
    public.compute_level(bigint),
    public.is_cohort_valid(text, text),
    public.department_of(text)
to anon, authenticated;

-- the PWA's RPC surface (all enforce auth.uid() internally)
grant execute on function
    public.accept_trade(uuid),
    public.resolve_trade(uuid, text),
    public.create_trade(uuid, uuid[], uuid[]),
    public.list_my_trades(text),
    public.player_unique_cards(uuid),
    public.search_players(text),
    public.validate_deck_spec(text, uuid, jsonb),
    public.my_profile_stats(uuid),
    public.leaderboard_full(text, text, text, text, integer),
    public.popular_decks(integer),
    public.active_buildings(integer),
    public.achievement_catalog()
to authenticated;

-- future functions created by this role start locked down too; grant explicitly.
alter default privileges in schema public revoke execute on functions from anon, authenticated;
alter default privileges revoke execute on functions from public;

-- ******************** FILE: migrations/20260924000014_starter_pack.sql ********************
-- Campus Forge → Supabase
-- Migration 14: starter pack so every account can battle on day one.
--
-- Starter creatures: 5 red + 5 green attacking creatures become UNLIMITED,
-- exactly like basic lands: every player owns infinite copies and can build
-- any deck with them (format rules still apply: max 4 copies per deck in
-- STANDARD). Scanning their QR codes still counts as a discovery (no XP).
--
-- grant_starter_pack(player):
--   * builds a legal 60-card STANDARD deck "Red-Green Starter":
--     4x each of the 10 creatures + 10 Mountain + 10 Forest,
--   * logs a STARTER row in game_log, which is also the idempotency marker
--     (a player who deletes the deck does not get a new one). If the catalog
--     is not seeded yet nothing is marked, so re-running the backfill at the
--     bottom of this file completes the grant.
-- No XP, unlocks or discoveries are granted, so scan-based achievements still
-- have to be earned.
--
-- handle_new_user now also copies a *valid* cohort from signup metadata and
-- calls grant_starter_pack; a failure there is logged as a warning and never
-- blocks signup. Existing players are backfilled once at the end.
--
-- Idempotent.

-- ---------------------------------------------------------------
-- Starter creatures are UNLIMITED (seed.sql matches for fresh installs).
-- ---------------------------------------------------------------
update public.cards
   set ownership_type = 'UNLIMITED'
 where ownership_type <> 'UNLIMITED'
   and forge_name in ('Raging Goblin', 'Goblin Piker', 'Vulshok Berserker', 'Hill Giant', 'Fire Elemental',
                      'Grizzly Bears', 'Elvish Warrior', 'Trained Armodon', 'War Mammoth', 'Craw Wurm');

create or replace function public.grant_starter_pack(p_player uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    -- mana curve 1-2-3-4-5 (red) / 2-2-3-4-6 (green); all vanilla-ish beaters
    v_red   constant text[] := array['Raging Goblin', 'Goblin Piker', 'Vulshok Berserker', 'Hill Giant', 'Fire Elemental'];
    v_green constant text[] := array['Grizzly Bears', 'Elvish Warrior', 'Trained Armodon', 'War Mammoth', 'Craw Wurm'];
    v_names text[] := v_red || v_green;
    v_ids   uuid[];
    v_mountain uuid;
    v_forest   uuid;
    v_deck  uuid := null;
begin
    if p_player is null or not exists (select 1 from public.profiles where id = p_player) then
        return;
    end if;
    if exists (select 1 from public.game_log where kind = 'STARTER' and player_id = p_player) then
        return;
    end if;

    select array_agg(id) into v_ids
      from public.cards
     where forge_name = any (v_names) and ownership_type = 'UNLIMITED';

    select id into v_mountain from public.cards where forge_name = 'Mountain' and ownership_type = 'UNLIMITED' limit 1;
    select id into v_forest   from public.cards where forge_name = 'Forest'   and ownership_type = 'UNLIMITED' limit 1;

    -- only build the deck when the whole roster is in the catalog (it must be legal)
    if coalesce(array_length(v_ids, 1), 0) = array_length(v_names, 1)
       and v_mountain is not null and v_forest is not null then
        v_deck := gen_random_uuid();
        insert into public.decks (id, player_id, name, format_code)
        values (v_deck, p_player, 'Red-Green Starter', 'STANDARD');

        insert into public.deck_cards (id, deck_id, card_id, quantity)
        select gen_random_uuid(), v_deck, c, 4 from unnest(v_ids) as c
        union all
        select gen_random_uuid(), v_deck, v_mountain, 10
        union all
        select gen_random_uuid(), v_deck, v_forest, 10;
    end if;

    -- no marker unless the full pack landed, so a later backfill can finish the job
    if v_deck is null then
        raise warning 'starter pack incomplete for % (catalog not seeded?)', p_player;
        return;
    end if;

    insert into public.game_log (kind, player_id, ref_id, detail)
    values ('STARTER', p_player, v_deck, jsonb_build_object(
        'cards', (select coalesce(jsonb_agg(forge_name order by forge_name), '[]'::jsonb)
                    from public.cards where id = any (coalesce(v_ids, '{}'::uuid[]))),
        'deckId', v_deck));
end;
$$;

revoke execute on function public.grant_starter_pack(uuid) from public, anon, authenticated;
grant execute on function public.grant_starter_pack(uuid) to service_role;

-- ---------------------------------------------------------------
-- Signup hook: profile row + valid cohort from metadata + starter pack.
-- ---------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
    v_name text := btrim(coalesce(v_meta ->> 'display_name', v_meta ->> 'name', ''));
    v_deg  text := upper(nullif(btrim(v_meta ->> 'degree_level'), ''));
    v_spec text := upper(nullif(btrim(v_meta ->> 'specialization'), ''));
    v_ok   boolean;
begin
    if v_name = '' then
        v_name := split_part(new.email, '@', 1);
    end if;
    v_ok := coalesce(public.is_cohort_valid(v_deg, v_spec), false);

    insert into public.profiles (id, display_name, email, degree_level, specialization)
    values (
        new.id,
        left(coalesce(nullif(v_name, ''), 'player'), 40),
        new.email,
        case when v_ok then v_deg end,
        case when v_ok then v_spec end
    )
    on conflict (id) do nothing;

    begin
        perform public.grant_starter_pack(new.id);
    exception when others then
        raise warning 'grant_starter_pack failed for %: %', new.id, sqlerrm;
    end;

    return new;
end;
$$;

revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- ---------------------------------------------------------------
-- Backfill: every existing player gets the pack once.
-- ---------------------------------------------------------------
select public.grant_starter_pack(p.id) from public.profiles p;

-- ******************** FILE: migrations/20260924000015_app_config.sql ********************
-- Campus Forge → Supabase
-- Migration 15: public runtime configuration (app_config).
--
-- Key/value settings the PWA reads at startup, so they can change without
-- rebuilding the GitHub Pages bundle. First use: `battle_engine_url`, the
-- current public URL of the battle engine. A Cloudflare quick tunnel gets a
-- new *.trycloudflare.com URL on every start; battle-engine/start-public.ps1
-- writes it here (service role) and clears it on shutdown, and clients pick
-- it up on load and live via Realtime.
--
-- Everything in this table is PUBLIC (readable without signing in). Never
-- store secrets here. Only the service role / admins write.
--
-- Idempotent.

create table if not exists public.app_config (
    key        text primary key check (key ~ '^[a-z][a-z0-9_]{1,62}$'),
    value      text,
    updated_at timestamptz not null default now()
);

alter table public.app_config enable row level security;

drop policy if exists app_config_select_all on public.app_config;
create policy app_config_select_all on public.app_config for select
to anon, authenticated
using (true);

drop policy if exists app_config_admin_all on public.app_config;
create policy app_config_admin_all on public.app_config for all
to authenticated
using (public.is_admin())
with check (public.is_admin());

revoke insert, update, delete, truncate on public.app_config from anon;

create or replace function public.touch_app_config()
returns trigger
language plpgsql
as $$
begin
    new.updated_at := now();
    return new;
end;
$$;

revoke execute on function public.touch_app_config() from public, anon, authenticated;

drop trigger if exists trg_app_config_touch on public.app_config;
create trigger trg_app_config_touch
before insert or update on public.app_config
for each row execute function public.touch_app_config();

insert into public.app_config (key, value) values ('battle_engine_url', null)
on conflict (key) do nothing;

do $$
begin
    if not exists (
        select 1 from pg_publication_tables
        where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'app_config'
    ) then
        alter publication supabase_realtime add table public.app_config;
    end if;
end;
$$;

-- ******************** FILE: migrations/20260925000016_multi_copy_unlocks.sql ********************
-- Campus Forge → Supabase
-- Migration 16: collect up to 4 copies of an UNLOCK card by scanning 4 different codes.
--
-- Before: player_unlocks was unique per (player, card), so a player owned at
-- most ONE copy of every UNLOCK card, however many codes they found.
--
-- Now:
--   * every unlock row records the claim (QR code) that granted it
--     (player_unlocks.claim_id); a code gives a player at most one copy
--     (unique (player_id, claim_id)), and each DIFFERENT code for the same
--     card adds a copy, up to 4 (the Standard per-deck maximum);
--   * each new copy is worth the usual 10 XP × event bonus; rescanning a code
--     you already used, or scanning a 5th code, only bumps the discovery count;
--   * a per-player-per-card advisory lock stops two concurrent scans from
--     overshooting the cap;
--   * UNIQUE cards: a player who already holds a serial of a card can no
--     longer claim a second one by scanning; the code is NOT consumed (it
--     used to be burned without granting anything), so someone else can have it;
--   * the claim result tells the app how many copies you now own and why a
--     scan granted nothing (reason: SAME_CODE | MAX_COPIES | UNLIMITED).
--
-- Copy quantities are already read as row counts everywhere else
-- (validate_deck_spec, validate_deck, the collection page), so no other change
-- is needed. Pre-existing unlock rows keep claim_id = null and count as copies.
--
-- Idempotent.

alter table public.player_unlocks
    add column if not exists claim_id uuid references public.claims (id) on delete set null;

do $$
begin
    if exists (select 1 from pg_constraint where conname = 'uk_player_unlocks_player_card') then
        alter table public.player_unlocks drop constraint uk_player_unlocks_player_card;
    end if;
    if not exists (select 1 from pg_constraint where conname = 'uk_player_unlocks_player_claim') then
        alter table public.player_unlocks
            add constraint uk_player_unlocks_player_claim unique (player_id, claim_id);
    end if;
end;
$$;

create index if not exists idx_player_unlocks_player_card on public.player_unlocks (player_id, card_id);

-- ---------------------------------------------------------------
-- apply_claim: multi-copy unlocks, unique-card guard, richer result.
-- ---------------------------------------------------------------
create or replace function public.apply_claim(p_core text, p_player uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_max_copies constant integer := 4;   -- per UNLOCK card, one per distinct code
    c          public.claims%rowtype;
    v_card     public.cards%rowtype;
    v_count    bigint;
    v_unlocked boolean := false;
    v_reason   text := null;
    v_copies   integer := null;
    v_xp       bigint := 0;
    v_phys     uuid := null;
    v_serial   integer;
    v_bonus    numeric := 1.00;
begin
    perform public.assert_active_player(p_player);

    select * into c from public.claims where token_core = p_core for update;
    if not found then
        raise exception 'Claim token not found: %', p_core using errcode = 'CF404';
    end if;

    select * into v_card from public.cards where id = c.card_id;
    if not found then
        raise exception 'unknown card' using errcode = 'CF404';
    end if;

    if c.status = 'REVOKED' then
        raise exception 'Claim token has been revoked' using errcode = 'CF410';
    end if;
    if c.expires_at is not null and c.expires_at < now() then
        update public.claims set status = 'EXPIRED' where id = c.id;
        raise exception 'Claim token has expired' using errcode = 'CF410';
    end if;
    if v_card.ownership_type = 'UNIQUE' and c.claimed_by is not null then
        raise exception 'This unique card has already been claimed' using errcode = 'CF409';
    end if;
    if c.status <> 'ACTIVE' then
        raise exception 'Claim token is no longer active' using errcode = 'CF410';
    end if;
    -- serialize concurrent scans by the same player for the same card, so the
    -- copy cap and the one-unique-per-player rule below can't be raced
    perform pg_advisory_xact_lock(hashtextextended(p_player::text || ':' || v_card.id::text, 0));

    if v_card.ownership_type = 'UNIQUE'
       and exists (select 1 from public.unique_cards uq where uq.owner_id = p_player and uq.card_id = v_card.id) then
        raise exception 'You already own a copy of this unique card; leave this one for someone else'
            using errcode = 'CF409';
    end if;

    insert into public.discoveries (id, player_id, card_id, count, last_discovered)
    values (gen_random_uuid(), p_player, c.card_id, 1, now())
    on conflict on constraint uk_discoveries_player_card do update
    set count = public.discoveries.count + 1,
        last_discovered = now();

    select d.count into v_count
      from public.discoveries d
     where d.player_id = p_player and d.card_id = c.card_id;

    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.active = true and e.start_time <= now() and e.end_time >= now()
     order by e.start_time
     limit 1;
    if not found then
        v_bonus := 1.00;
    end if;

    if v_card.ownership_type = 'UNLOCK' then
        select count(*)::integer into v_copies
          from public.player_unlocks where player_id = p_player and card_id = v_card.id;
        if exists (select 1 from public.player_unlocks where player_id = p_player and claim_id = c.id) then
            v_reason := 'SAME_CODE';
        elsif v_copies >= v_max_copies then
            v_reason := 'MAX_COPIES';
        else
            insert into public.player_unlocks (id, player_id, card_id, unlocked_at, claim_id)
            values (gen_random_uuid(), p_player, v_card.id, now(), c.id);
            v_copies := v_copies + 1;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        end if;
    elsif v_card.ownership_type = 'UNIQUE' then
        select coalesce(max(uq.serial_number), 0) + 1 into v_serial
          from public.unique_cards uq where uq.card_id = v_card.id;
        v_phys := public.unique_physical_uuid(c.token_core);
        insert into public.unique_cards (physical_uuid, owner_id, card_id, serial_number, history)
        values (v_phys, p_player, c.card_id, v_serial, 'claimed via discovery')
        on conflict (physical_uuid) do nothing;
        v_copies := 1;
        v_unlocked := true;
        v_xp := round(10 * v_bonus)::bigint;
    else
        v_reason := 'UNLIMITED';
    end if;

    if v_unlocked then
        update public.profiles set experience = experience + v_xp where id = p_player;
        perform public.add_feed_entry('DISCOVERY',
            case when v_card.ownership_type = 'UNLOCK' and v_copies > 1
                 then 'found copy ' || v_copies || ' of ' || v_card.forge_name
                 else 'discovered ' || v_card.forge_name end,
            p_player, v_card.id);
    else
        perform public.add_feed_entry('DISCOVERY', 'scanned ' || v_card.forge_name, p_player, v_card.id);
    end if;

    if v_card.ownership_type = 'UNIQUE' then
        update public.claims set status = 'CLAIMED', claimed_by = p_player, claimed_at = now()
         where id = c.id;
    else
        update public.claims set claimed_by = p_player, claimed_at = now() where id = c.id;
    end if;

    insert into public.game_log (kind, player_id, card_id, ref_id, xp, detail)
    values ('CLAIM', p_player, v_card.id, c.id, v_xp, jsonb_build_object(
        'unlocked', v_unlocked,
        'reason', v_reason,
        'copiesOwned', v_copies,
        'building', c.building,
        'eventId', c.event_id,
        'bonus', v_bonus,
        'discoveryCount', v_count,
        'physicalUuid', v_phys));

    return jsonb_build_object(
        'card', jsonb_build_object(
            'id', v_card.id,
            'oracleId', v_card.oracle_id,
            'forgeName', v_card.forge_name,
            'rarity', v_card.rarity,
            'ownershipType', v_card.ownership_type,
            'setCode', v_card.set_code,
            'manaValue', v_card.mana_value,
            'types', v_card.types,
            'colors', v_card.colors,
            'imageUrl', v_card.image_url,
            'discoverable', v_card.discoverable,
            'spawnRegion', v_card.spawn_region,
            'weight', v_card.weight,
            'commanderEligible', v_card.commander_eligible
        ),
        'unlocked', v_unlocked,
        'alreadyOwned', (not v_unlocked),
        'reason', v_reason,
        'copiesOwned', v_copies,
        'maxCopies', case when v_card.ownership_type = 'UNLOCK' then v_max_copies end,
        'discoveryCount', v_count,
        'experienceAwarded', v_xp,
        'token', c.token,
        'building', c.building,
        'physicalUuid', v_phys
    );
end;
$$;

revoke execute on function public.apply_claim(text, uuid) from public, anon, authenticated;
grant execute on function public.apply_claim(text, uuid) to service_role;

-- ******************** FILE: migrations/20260925000017_scan_to_unlock_unlimited.sql ********************
-- Campus Forge → Supabase
-- Migration 17: UNLIMITED cards (other than the base 15) must be scanned once.
--
-- Before: every UNLIMITED card (basic lands, the 10 starter creatures and all
-- imported-set commons) was owned by everyone from the start.
--
-- Now: cards.requires_unlock marks UNLIMITED cards that are locked until the
-- player scans ANY code for them once; after that the player owns unlimited
-- copies. The base 15 (5 basic lands + 10 starter creatures) stay free.
--
--   * owned_copies(player, card) is the single ownership rule, used by
--     apply_claim, validate_deck_spec and validate_deck:
--       UNLIMITED → unlimited if free or unlocked, else 0
--       UNLOCK    → number of player_unlocks rows (one per distinct code, ≤ 4)
--       UNIQUE    → number of serials owned
--   * collection-% queries (achievements, profile stats, leaderboard) count an
--     UNLIMITED card as owned only if it is free or unlocked;
--   * apply_claim: the first scan of a locked UNLIMITED card unlocks it
--     (player_unlocks row, +10 XP × event bonus); later scans are
--     discovery-only (reason UNLIMITED);
--   * all imported-set commons already in the catalog are flagged.
--
-- Idempotent.

alter table public.cards add column if not exists requires_unlock boolean not null default false;

update public.cards
   set requires_unlock = true
 where ownership_type = 'UNLIMITED'
   and requires_unlock = false
   and forge_name not in ('Plains', 'Island', 'Swamp', 'Mountain', 'Forest',
                          'Raging Goblin', 'Goblin Piker', 'Vulshok Berserker', 'Hill Giant', 'Fire Elemental',
                          'Grizzly Bears', 'Elvish Warrior', 'Trained Armodon', 'War Mammoth', 'Craw Wurm');

-- ---------------------------------------------------------------
-- The ownership rule (copies a player may use in a deck).
-- ---------------------------------------------------------------
create or replace function public.owned_copies(p_player uuid, p_card uuid)
returns integer
language sql
stable
set search_path = public
as $$
    select case c.ownership_type
        when 'UNLIMITED' then
            case when not c.requires_unlock
                   or exists (select 1 from public.player_unlocks u where u.player_id = p_player and u.card_id = c.id)
                 then 2147483647 else 0 end
        when 'UNLOCK' then
            (select count(*)::integer from public.player_unlocks u where u.player_id = p_player and u.card_id = c.id)
        else
            (select count(*)::integer from public.unique_cards uc where uc.owner_id = p_player and uc.card_id = c.id)
    end
    from public.cards c
    where c.id = p_card;
$$;

revoke execute on function public.owned_copies(uuid, uuid) from public, anon, authenticated;
grant execute on function public.owned_copies(uuid, uuid) to service_role;

-- ---------------------------------------------------------------
-- apply_claim (migration 16) + first scan unlocks locked UNLIMITED cards.
-- ---------------------------------------------------------------
create or replace function public.apply_claim(p_core text, p_player uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_max_copies constant integer := 4;   -- per UNLOCK card, one per distinct code
    c          public.claims%rowtype;
    v_card     public.cards%rowtype;
    v_count    bigint;
    v_unlocked boolean := false;
    v_reason   text := null;
    v_copies   integer := null;
    v_xp       bigint := 0;
    v_phys     uuid := null;
    v_serial   integer;
    v_bonus    numeric := 1.00;
begin
    perform public.assert_active_player(p_player);

    select * into c from public.claims where token_core = p_core for update;
    if not found then
        raise exception 'Claim token not found: %', p_core using errcode = 'CF404';
    end if;

    select * into v_card from public.cards where id = c.card_id;
    if not found then
        raise exception 'unknown card' using errcode = 'CF404';
    end if;

    if c.status = 'REVOKED' then
        raise exception 'Claim token has been revoked' using errcode = 'CF410';
    end if;
    if c.expires_at is not null and c.expires_at < now() then
        update public.claims set status = 'EXPIRED' where id = c.id;
        raise exception 'Claim token has expired' using errcode = 'CF410';
    end if;
    if v_card.ownership_type = 'UNIQUE' and c.claimed_by is not null then
        raise exception 'This unique card has already been claimed' using errcode = 'CF409';
    end if;
    if c.status <> 'ACTIVE' then
        raise exception 'Claim token is no longer active' using errcode = 'CF410';
    end if;

    -- serialize concurrent scans by the same player for the same card, so the
    -- copy cap and the one-unique-per-player rule below can't be raced
    perform pg_advisory_xact_lock(hashtextextended(p_player::text || ':' || v_card.id::text, 0));

    if v_card.ownership_type = 'UNIQUE'
       and exists (select 1 from public.unique_cards uq where uq.owner_id = p_player and uq.card_id = v_card.id) then
        raise exception 'You already own a copy of this unique card; leave this one for someone else'
            using errcode = 'CF409';
    end if;

    insert into public.discoveries (id, player_id, card_id, count, last_discovered)
    values (gen_random_uuid(), p_player, c.card_id, 1, now())
    on conflict on constraint uk_discoveries_player_card do update
    set count = public.discoveries.count + 1,
        last_discovered = now();

    select d.count into v_count
      from public.discoveries d
     where d.player_id = p_player and d.card_id = c.card_id;

    select e.bonus_multiplier into v_bonus
      from public.events e
     where e.active = true and e.start_time <= now() and e.end_time >= now()
     order by e.start_time
     limit 1;
    if not found then
        v_bonus := 1.00;
    end if;

    if v_card.ownership_type = 'UNLOCK' then
        select count(*)::integer into v_copies
          from public.player_unlocks where player_id = p_player and card_id = v_card.id;
        if exists (select 1 from public.player_unlocks where player_id = p_player and claim_id = c.id) then
            v_reason := 'SAME_CODE';
        elsif v_copies >= v_max_copies then
            v_reason := 'MAX_COPIES';
        else
            insert into public.player_unlocks (id, player_id, card_id, unlocked_at, claim_id)
            values (gen_random_uuid(), p_player, v_card.id, now(), c.id);
            v_copies := v_copies + 1;
            v_unlocked := true;
            v_xp := round(10 * v_bonus)::bigint;
        end if;
    elsif v_card.ownership_type = 'UNIQUE' then
        select coalesce(max(uq.serial_number), 0) + 1 into v_serial
          from public.unique_cards uq where uq.card_id = v_card.id;
        v_phys := public.unique_physical_uuid(c.token_core);
        insert into public.unique_cards (physical_uuid, owner_id, card_id, serial_number, history)
        values (v_phys, p_player, c.card_id, v_serial, 'claimed via discovery')
        on conflict (physical_uuid) do nothing;
        v_copies := 1;
        v_unlocked := true;
        v_xp := round(10 * v_bonus)::bigint;
    elsif v_card.requires_unlock
          and not exists (select 1 from public.player_unlocks where player_id = p_player and card_id = v_card.id) then
        -- UNLIMITED but locked: this first scan unlocks unlimited copies
        insert into public.player_unlocks (id, player_id, card_id, unlocked_at, claim_id)
        values (gen_random_uuid(), p_player, v_card.id, now(), c.id);
        v_unlocked := true;
        v_xp := round(10 * v_bonus)::bigint;
    else
        v_reason := 'UNLIMITED';
    end if;

    if v_unlocked then
        update public.profiles set experience = experience + v_xp where id = p_player;
        perform public.add_feed_entry('DISCOVERY',
            case when v_card.ownership_type = 'UNLOCK' and v_copies > 1
                 then 'found copy ' || v_copies || ' of ' || v_card.forge_name
                 else 'discovered ' || v_card.forge_name end,
            p_player, v_card.id);
    else
        perform public.add_feed_entry('DISCOVERY', 'scanned ' || v_card.forge_name, p_player, v_card.id);
    end if;

    if v_card.ownership_type = 'UNIQUE' then
        update public.claims set status = 'CLAIMED', claimed_by = p_player, claimed_at = now()
         where id = c.id;
    else
        update public.claims set claimed_by = p_player, claimed_at = now() where id = c.id;
    end if;

    insert into public.game_log (kind, player_id, card_id, ref_id, xp, detail)
    values ('CLAIM', p_player, v_card.id, c.id, v_xp, jsonb_build_object(
        'unlocked', v_unlocked,
        'reason', v_reason,
        'copiesOwned', v_copies,
        'building', c.building,
        'eventId', c.event_id,
        'bonus', v_bonus,
        'discoveryCount', v_count,
        'physicalUuid', v_phys));

    return jsonb_build_object(
        'card', jsonb_build_object(
            'id', v_card.id,
            'oracleId', v_card.oracle_id,
            'forgeName', v_card.forge_name,
            'rarity', v_card.rarity,
            'ownershipType', v_card.ownership_type,
            'requiresUnlock', v_card.requires_unlock,
            'setCode', v_card.set_code,
            'manaValue', v_card.mana_value,
            'types', v_card.types,
            'colors', v_card.colors,
            'imageUrl', v_card.image_url,
            'discoverable', v_card.discoverable,
            'spawnRegion', v_card.spawn_region,
            'weight', v_card.weight,
            'commanderEligible', v_card.commander_eligible
        ),
        'unlocked', v_unlocked,
        'alreadyOwned', (not v_unlocked),
        'reason', v_reason,
        'copiesOwned', v_copies,
        'maxCopies', case when v_card.ownership_type = 'UNLOCK' then v_max_copies end,
        'discoveryCount', v_count,
        'experienceAwarded', v_xp,
        'token', c.token,
        'building', c.building,
        'physicalUuid', v_phys
    );
end;
$$;

revoke execute on function public.apply_claim(text, uuid) from public, anon, authenticated;
grant execute on function public.apply_claim(text, uuid) to service_role;

-- ---------------------------------------------------------------
-- validate_deck_spec (migration 11) with owned_copies(); also fixes the
-- color-identity check for multicolor cards (string_to_array(x, '') does not
-- split into characters; a NULL delimiter does).
-- ---------------------------------------------------------------
create or replace function public.validate_deck_spec(
    p_format_code  text,
    p_commander    uuid,
    p_cards        jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid       uuid := auth.uid();
    f           public.formats%rowtype;
    v_problems  jsonb := '[]'::jsonb;
    e           record;
    v_card      record;
    v_owned_qty bigint;
    v_leg       text;
    v_basic     boolean;
    v_total     integer := 0;
    v_cmdr      record;
    v_cmdr_colors text;
    v_colors    text;
    v_ch        text;
    v_entry     record;
    v_color_ok  boolean;
begin
    select * into f from public.formats where code = p_format_code;
    if not found then
        return jsonb_build_object('valid', false, 'problems', jsonb_build_array(
            jsonb_build_object('code', 'UNKNOWN_FORMAT', 'message', 'Unknown format: ' || p_format_code, 'cardId', null)
        ));
    end if;

    for e in
        select (elem->>'cardId')::uuid as card_id,
               sum(coalesce((elem->>'quantity')::integer, 0))::integer as qty
        from jsonb_array_elements(coalesce(p_cards, '[]'::jsonb)) as elem
        where elem->>'cardId' is not null
        group by 1
    loop
        v_card := null;
        select c.id, c.forge_name, c.ownership_type, c.colors, c.types, c.commander_eligible
          into v_card
          from public.cards c where c.id = e.card_id;
        if not found then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'UNKNOWN_CARD', 'message', 'Unknown card: ' || e.card_id, 'cardId', e.card_id));
            continue;
        end if;

        v_owned_qty := coalesce(public.owned_copies(v_uid, e.card_id), 0);

        if v_owned_qty = 0 then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NOT_OWNED', 'message', 'You do not own: ' || v_card.forge_name, 'cardId', e.card_id));
        end if;
        if v_owned_qty < e.qty then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NOT_ENOUGH_COPIES',
                'message', 'Only ' || v_owned_qty || ' owned of: ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        select legality into v_leg from public.card_legalities
         where card_id = e.card_id and format_id = f.id;
        if v_leg = 'BANNED' then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'BANNED', 'message', 'Banned in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        elsif v_leg = 'RESTRICTED' and e.qty > 1 then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'RESTRICTED', 'message', 'Restricted to 1 copy in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        v_basic := v_card.types is not null and v_card.types like '%Basic Land%';
        if not (f.basics_unlimited and v_basic) and e.qty > f.max_copies then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'TOO_MANY_COPIES', 'message',
                'Max ' || f.max_copies || ' copies in ' || f.name || ': ' || v_card.forge_name,
                'cardId', e.card_id));
        end if;

        v_total := v_total + e.qty;
    end loop;

    if v_total < f.min_deck_size then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
            'code', 'TOO_FEW_CARDS', 'message',
            'Minimum ' || f.min_deck_size || ' cards, got ' || v_total, 'cardId', null));
    end if;
    if f.max_deck_size is not null and v_total > f.max_deck_size then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
            'code', 'TOO_MANY_CARDS', 'message',
            'Maximum ' || f.max_deck_size || ' cards, got ' || v_total, 'cardId', null));
    end if;

    if f.commander_required then
        if p_commander is null then
            v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                'code', 'NO_COMMANDER', 'message', 'A commander is required.', 'cardId', null));
        else
            v_cmdr := null;
            select c.id, c.forge_name, c.colors, c.commander_eligible
              into v_cmdr
              from public.cards c where c.id = p_commander;
            if not found then
                v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                    'code', 'UNKNOWN_COMMANDER', 'message', 'Unknown commander card', 'cardId', p_commander));
            else
                if coalesce(public.owned_copies(v_uid, v_cmdr.id), 0) = 0 then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'COMMANDER_NOT_OWNED', 'message', 'You do not own: ' || v_cmdr.forge_name,
                        'cardId', v_cmdr.id));
                end if;
                if not v_cmdr.commander_eligible then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'NOT_LEGENDARY', 'message', v_cmdr.forge_name || ' cannot be a commander.',
                        'cardId', v_cmdr.id));
                end if;
                select legality into v_leg from public.card_legalities
                 where card_id = v_cmdr.id and format_id = f.id;
                if v_leg = 'BANNED' then
                    v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                        'code', 'BANNED_COMMANDER', 'message', v_cmdr.forge_name || ' is banned as commander.',
                        'cardId', v_cmdr.id));
                end if;

                v_cmdr_colors := coalesce(v_cmdr.colors, '');

                -- color identity: every card's colors must be a subset of the commander's
                for v_entry in
                    select c.id, c.forge_name, c.colors
                    from public.cards c
                    where c.id in (
                        select (elem->>'cardId')::uuid
                        from jsonb_array_elements(coalesce(p_cards, '[]'::jsonb)) elem
                        where elem->>'cardId' is not null
                        union
                        select p_commander
                    )
                loop
                    v_colors := coalesce(v_entry.colors, '');
                    v_color_ok := true;
                    for v_ch in select * from unnest(string_to_array(v_colors, null)) loop
                        if position(v_ch in v_cmdr_colors) = 0 then
                            v_color_ok := false;
                            exit;
                        end if;
                    end loop;
                    if not v_color_ok then
                        v_problems := v_problems || jsonb_build_array(jsonb_build_object(
                            'code', 'COLOR_IDENTITY', 'message',
                            v_entry.forge_name || ' (colors ' || v_colors || ') is outside '
                                || v_cmdr.forge_name || '''s color identity (' || v_cmdr_colors || ').',
                            'cardId', v_entry.id));
                    end if;
                end loop;
            end if;
        end if;
    end if;

    return jsonb_build_object('valid', (v_problems = '[]'::jsonb), 'problems', v_problems);
end;
$$;

revoke execute on function public.validate_deck_spec(text, uuid, jsonb) from public, anon;
grant execute on function public.validate_deck_spec(text, uuid, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------
-- validate_deck (migration 13, battle time) with owned_copies().
-- ---------------------------------------------------------------
create or replace function public.validate_deck(
    p_deck  uuid,
    p_event uuid default null
)
returns setof public.deck_problem
language plpgsql
security definer
set search_path = public
as $$
declare
    d         public.decks%rowtype;
    f         public.formats%rowtype;
    v_total   integer;
    v_allowed jsonb;
    e         record;
begin
    select * into d from public.decks where id = p_deck;
    if not found then
        return next row('ERROR', 'NOT_FOUND', 'deck not found')::public.deck_problem;
        return;
    end if;

    select * into f from public.formats where code = d.format_code;
    if not found then
        return next row('ERROR', 'UNKNOWN_FORMAT', format('unknown format %s', d.format_code))::public.deck_problem;
        return;
    end if;

    if p_event is not null then
        select allowed_sets_json::jsonb into v_allowed from public.events where id = p_event and active = true;
    end if;

    select coalesce(sum(dc.quantity), 0)::integer into v_total
      from public.deck_cards dc where dc.deck_id = p_deck;

    for e in
        select c.id, c.forge_name, c.set_code, dc.quantity,
               coalesce(c.types ilike '%Basic%', false) as basic,
               coalesce(public.owned_copies(d.player_id, c.id), 0) as owned_qty,
               exists (select 1 from public.card_legalities cl
                        where cl.card_id = c.id and cl.format_id = f.id and cl.legality = 'BANNED') as banned
          from public.deck_cards dc
          join public.cards c on c.id = dc.card_id
         where dc.deck_id = p_deck
    loop
        if e.owned_qty = 0 then
            return next row('ERROR', 'NOT_OWNED', format('%s is not owned by the player', e.forge_name))::public.deck_problem;
        elsif e.owned_qty < e.quantity then
            return next row('ERROR', 'NOT_ENOUGH_COPIES', format('only %s owned of %s', e.owned_qty, e.forge_name))::public.deck_problem;
        end if;
        if not (f.basics_unlimited and e.basic) and e.quantity > f.max_copies then
            return next row('ERROR', 'TOO_MANY_COPIES', format('%s exceeds max copies of %s', e.forge_name, f.max_copies))::public.deck_problem;
        end if;
        if e.banned then
            return next row('ERROR', 'BANNED_CARD', format('%s is banned in %s', e.forge_name, f.name))::public.deck_problem;
        end if;
        if v_allowed is not null and not e.basic
           and (e.set_code is null or not (e.set_code = any (select jsonb_array_elements_text(v_allowed)))) then
            return next row('ERROR', 'NOT_IN_EVENT', format('%s is not in the event allowed sets', e.forge_name))::public.deck_problem;
        end if;
    end loop;

    if v_total < f.min_deck_size then
        return next row('WARNING', 'NOT_ENOUGH_CARDS', format('deck has %s cards, requires %s', v_total, f.min_deck_size))::public.deck_problem;
    end if;
    if f.max_deck_size is not null and v_total > f.max_deck_size then
        return next row('ERROR', 'TOO_MANY_CARDS', format('deck has %s cards, maximum %s', v_total, f.max_deck_size))::public.deck_problem;
    end if;
    if f.commander_required and d.commander_card_id is null then
        return next row('ERROR', 'NO_COMMANDER', 'a commander is required')::public.deck_problem;
    end if;
end;
$$;

revoke execute on function public.validate_deck(uuid, uuid) from public, anon, authenticated;
grant execute on function public.validate_deck(uuid, uuid) to service_role;

-- ---------------------------------------------------------------
-- sweep_achievements (migration 11): collection % counts locked UNLIMITED
-- cards only once unlocked.
-- ---------------------------------------------------------------
create or replace function public.sweep_achievements(p_player uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_level    integer;
    v_disc     bigint;
    v_played   integer;
    v_wins     integer;
    v_owned    integer;
    v_total    integer;
    v_comp     integer;
    v_trades   bigint;
    v_undef    integer;
    ac         record;
    v_value    bigint;
begin
    if p_player is null then
        return;
    end if;

    select public.compute_level(p.experience) into v_level
      from public.profiles p where p.id = p_player;
    if not found then
        return;
    end if;

    select coalesce(sum(count), 0) into v_disc
      from public.discoveries where player_id = p_player;

    select count(*) into v_played from public.matches
     where (player1_id = p_player or player2_id = p_player)
       and status in ('FINISHED', 'CONCEDED');
    select count(*) into v_wins from public.matches
     where winner_id = p_player and status in ('FINISHED', 'CONCEDED');

    select count(*) into v_total from public.cards;
    select count(distinct c.id) into v_owned from public.cards c
     where (c.ownership_type = 'UNLIMITED' and not c.requires_unlock)
        or exists (select 1 from public.player_unlocks u where u.player_id = p_player and u.card_id = c.id)
        or exists (select 1 from public.unique_cards uc where uc.owner_id = p_player and uc.card_id = c.id);

    v_comp := case when v_total = 0 then 0 else round(100.0 * v_owned / v_total)::integer end;

    select count(*) into v_trades from public.trades
     where status = 'ACCEPTED' and (sender_id = p_player or receiver_id = p_player);

    v_undef := case when v_played >= 1 and v_wins = v_played then 1 else 0 end;

    for ac in select * from public.achievement_catalog() loop
        v_value := case ac.metric
            when 'DISCOVERIES'    then v_disc
            when 'BATTLES_WON'    then v_wins
            when 'UNIQUE_TRADES'  then v_trades
            when 'LEVEL'          then v_level
            when 'COLLECTION_PCT' then v_comp
            when 'UNDEFEATED'     then v_undef
            else 0
        end;
        if v_value >= ac.threshold then
            insert into public.player_achievements (id, player_id, code)
            values (gen_random_uuid(), p_player, ac.code)
            on conflict on constraint uk_player_achievements_player_code do nothing;
        end if;
    end loop;
end;
$$;

revoke execute on function public.sweep_achievements(uuid) from public, anon, authenticated;
grant execute on function public.sweep_achievements(uuid) to service_role;

-- ---------------------------------------------------------------
-- my_profile_stats (migration 13): same ownership rule.
-- ---------------------------------------------------------------
create or replace function public.my_profile_stats(p_player uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid       uuid := coalesce(p_player, auth.uid());
    v_exp       bigint;
    v_level     integer;
    v_xp_next   bigint;
    v_disc      bigint;
    v_owned     integer;
    v_total     integer;
    v_comp      integer;
    v_colors    text[];
    v_buildings text[];
    v_played    integer;
    v_wins      integer;
    v_losses    integer;
    v_rate      integer;
    v_player    jsonb;
    v_badges    jsonb;
begin
    if v_uid is null then
        return null;
    end if;
    if auth.uid() is not null and v_uid <> auth.uid() and not public.is_admin() then
        raise exception 'You can only view your own stats' using errcode = 'CF403';
    end if;

    select
        p.experience,
        public.compute_level(p.experience),
        jsonb_build_object(
            'id', p.id, 'email', p.email, 'displayName', p.display_name, 'role', p.role,
            'avatar', p.avatar, 'studentId', p.student_id,
            'degreeLevel', p.degree_level, 'specialization', p.specialization,
            'experience', p.experience, 'level', public.compute_level(p.experience)
        )
    into v_exp, v_level, v_player
      from public.profiles p where p.id = v_uid;
    if not found then
        return null;
    end if;

    v_xp_next := greatest(0, (v_level * 100) - v_exp);

    select coalesce(sum(count), 0) into v_disc
      from public.discoveries where player_id = v_uid;

    select count(*) into v_total from public.cards;
    select count(distinct c.id) into v_owned from public.cards c
     where (c.ownership_type = 'UNLIMITED' and not c.requires_unlock)
        or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
        or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id);
    v_comp := case when v_total = 0 then 0 else round(100.0 * v_owned / v_total)::integer end;

    select array_agg(ch order by cnt desc, ch asc) into v_colors
    from (
        select ch, count(*) as cnt
        from (
            select c.id, c.colors
            from public.cards c
            where ((c.ownership_type = 'UNLIMITED' and not c.requires_unlock)
                   or exists (select 1 from public.player_unlocks u where u.player_id = v_uid and u.card_id = c.id)
                   or exists (select 1 from public.unique_cards uc where uc.owner_id = v_uid and uc.card_id = c.id))
              and coalesce(c.colors, '') <> ''
        ) owned,
        lateral unnest(string_to_array(upper(owned.colors), null)) as ch
        where ch in ('W', 'U', 'B', 'R', 'G')
        group by ch
        order by cnt desc, ch asc
        limit 3
    ) s;

    select array_agg(b order by b) into v_buildings
    from (
        select distinct btrim(building) as b
        from public.claims
        where claimed_by = v_uid and building is not null and btrim(building) <> ''
    ) s;

    select count(*) into v_played from public.matches
     where (player1_id = v_uid or player2_id = v_uid) and status in ('FINISHED', 'CONCEDED');
    select count(*) into v_wins from public.matches
     where winner_id = v_uid and status in ('FINISHED', 'CONCEDED');
    v_losses := v_played - v_wins;
    v_rate := case when v_played = 0 then 0 else round(100.0 * v_wins / v_played)::integer end;

    perform public.sweep_achievements(v_uid);
    select coalesce(jsonb_agg(jsonb_build_object('code', a.code, 'name', c.name, 'description', c.description)
                   order by a.unlocked_at), '[]'::jsonb)
      into v_badges
      from public.player_achievements a
      left join public.achievement_catalog() c on c.code = a.code
     where a.player_id = v_uid;

    return jsonb_build_object(
        'player', v_player,
        'experience', v_exp,
        'level', v_level,
        'experienceToNextLevel', v_xp_next,
        'collectionCompletionPercent', v_comp,
        'ownedCards', v_owned,
        'totalCards', v_total,
        'totalDiscoveries', v_disc,
        'favoriteColors', coalesce(v_colors, '{}'),
        'buildingsVisited', coalesce(v_buildings, '{}'),
        'battleStats', jsonb_build_object(
            'played', v_played, 'wins', v_wins, 'losses', v_losses, 'winRatePercent', v_rate
        ),
        'badges', v_badges
    );
end;
$$;

revoke execute on function public.my_profile_stats(uuid) from public, anon;
grant execute on function public.my_profile_stats(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------
-- leaderboard_full (migration 11): same ownership rule for 'collection'.
-- ---------------------------------------------------------------
create or replace function public.leaderboard_full(
    p_metric       text     default 'level',
    p_degree_level text     default null,
    p_specialization text   default null,
    p_department   text     default null,
    p_limit        integer  default 50
)
returns jsonb
language sql
security definer
set search_path = public
as $$
    with
    tot as (
        select count(*)::integer as n from public.cards
    ),
    base as (
        select
            p.id, p.display_name, p.avatar, p.degree_level, p.specialization,
            p.experience,
            public.compute_level(p.experience) as level,
            (select count(distinct c.id) from public.cards c
              where (c.ownership_type = 'UNLIMITED' and not c.requires_unlock)
                 or exists (select 1 from public.player_unlocks u where u.player_id = p.id and u.card_id = c.id)
                 or exists (select 1 from public.unique_cards uc where uc.owner_id = p.id and uc.card_id = c.id)
            ) as owned_count,
            (select count(*) from public.matches m
              where (m.player1_id = p.id or m.player2_id = p.id) and m.status in ('FINISHED', 'CONCEDED')) as played,
            (select count(*) from public.matches m
              where m.winner_id = p.id and m.status in ('FINISHED', 'CONCEDED')) as wins
        from public.profiles p
        where p.banned = false
          and (p_degree_level is null     or upper(p.degree_level) = upper(p_degree_level))
          and (p_specialization is null   or upper(p.specialization) = upper(p_specialization))
          and (p_department is null       or public.department_of(p.specialization) = upper(p_department))
    ),
    scored as (
        select
            b.*,
            case p_metric
                when 'collection' then case when t.n = 0 then 0 else round(100.0 * b.owned_count / t.n)::integer end
                when 'winrate'    then case when b.played = 0 then 0 else round(100.0 * b.wins / b.played)::integer end
                else b.level
            end as score,
            case p_metric
                when 'collection' then b.owned_count
                when 'winrate'    then b.wins
                else b.experience
            end as value,
            row_number() over (
                order by
                    case p_metric
                        when 'collection' then case when t.n = 0 then 0 else round(100.0 * b.owned_count / t.n)::integer end
                        when 'winrate'    then case when b.played = 0 then 0 else round(100.0 * b.wins / b.played)::integer end
                        else b.level
                    end desc,
                    case p_metric
                        when 'collection' then b.owned_count
                        when 'winrate'    then b.wins
                        else b.experience
                    end desc,
                    b.display_name asc
            ) as rn
        from base b
        cross join tot t
    )
    select jsonb_build_object(
        'rows', coalesce((
            select jsonb_agg(jsonb_build_object(
                'rank', s.rn, 'playerId', s.id, 'displayName', s.display_name,
                'avatar', s.avatar, 'degreeLevel', s.degree_level,
                'specialization', s.specialization, 'score', s.score, 'value', s.value)
            order by s.rn)
            from scored s
            where s.rn <= least(greatest(p_limit, 1), 100)
        ), '[]'::jsonb),
        'myRank', (select s.rn from scored s where s.id = auth.uid()),
        'total', (select count(*) from scored)
    );
$$;

revoke execute on function public.leaderboard_full(text, text, text, text, integer) from public, anon;
grant execute on function public.leaderboard_full(text, text, text, text, integer) to authenticated, service_role;

-- ******************** FILE: migrations/20260926000018_student_roster.sql ********************
-- ============================================================================
-- 18: student roster + roll-number accounts
--
-- Players sign in with their IIITD roll number instead of an email:
--   1. `students` holds the official roster (roll, name, program, batch), loaded
--      by scripts/import-students.mjs. It is personal data: service role and
--      admins only, never exposed to players.
--   2. The `student-auth` Edge Function checks roll + first name against it
--      (student_roll_status) and creates the auth user through the admin API
--      with app_metadata.roll_no. Only the admin API can set app_metadata, so a
--      public sign-up can never claim a roll number.
--   3. handle_new_user fills the profile from the roster: display name, cohort,
--      student id, roll_no. Players can't change roll_no, and roll accounts
--      can't change their student id or cohort either (trg_profiles_guard).
-- Email accounts (staff, older test accounts) keep working as before.
-- Idempotent.
-- ============================================================================

create table if not exists public.students (
    roll_no       text primary key check (roll_no ~ '^[0-9]{7}$'),
    name          text not null check (length(btrim(name)) between 1 and 80),
    program       text not null,
    batch         int  not null check (batch between 2000 and 2100),
    degree_level  text not null default 'BTECH',
    constraint students_cohort_valid check (public.is_cohort_valid(degree_level, program))
);

alter table public.students enable row level security;
revoke all on table public.students from public, anon, authenticated;
grant all on table public.students to service_role;

drop policy if exists students_admin_read on public.students;
create policy students_admin_read on public.students
    for select to authenticated using (public.is_admin());
grant select on table public.students to authenticated;   -- rows still gated by the admin-only policy

alter table public.profiles add column if not exists roll_no text;
do $$
begin
    if not exists (select 1 from pg_constraint where conname = 'profiles_roll_no_key') then
        alter table public.profiles add constraint profiles_roll_no_key unique (roll_no);
    end if;
    if not exists (select 1 from pg_constraint where conname = 'profiles_roll_no_fkey') then
        alter table public.profiles add constraint profiles_roll_no_fkey
            foreign key (roll_no) references public.students (roll_no) on update cascade;
    end if;
end;
$$;

-- ---------------------------------------------------------------
-- Name check: the typed first name must equal one word of the roster name
-- (letters only, case-insensitive), so "Mohd Rehan" accepts "mohd" or "Rehan".
-- ---------------------------------------------------------------
create or replace function public.student_name_matches(p_name text, p_typed text)
returns boolean
language sql
immutable
as $$
    with typed as (
        select lower(regexp_replace(split_part(btrim(coalesce(p_typed, '')), ' ', 1), '[^A-Za-z]', '', 'g')) as t
    )
    select length(typed.t) >= 2 and exists (
        select 1
        from regexp_split_to_table(coalesce(p_name, ''), '\s+') as w
        where lower(regexp_replace(w, '[^A-Za-z]', '', 'g')) = typed.t
    )
    from typed;
$$;

revoke execute on function public.student_name_matches(text, text) from public, anon, authenticated;
grant execute on function public.student_name_matches(text, text) to service_role;

-- ---------------------------------------------------------------
-- student_roll_status: what the login screen needs to know about a roll.
-- NOT_FOUND / NAME_MISMATCH reveal nothing else; the name and cohort are only
-- returned once the first name matched. Service role only (student-auth EF).
-- ---------------------------------------------------------------
create or replace function public.student_roll_status(p_roll text, p_first_name text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_student public.students%rowtype;
begin
    select * into v_student from public.students where roll_no = btrim(coalesce(p_roll, ''));
    if not found then
        return jsonb_build_object('status', 'NOT_FOUND');
    end if;
    if not public.student_name_matches(v_student.name, p_first_name) then
        return jsonb_build_object('status', 'NAME_MISMATCH');
    end if;
    return jsonb_build_object(
        'status', case when exists (select 1 from public.profiles where roll_no = v_student.roll_no)
                       then 'REGISTERED' else 'NEW' end,
        'rollNo', v_student.roll_no,
        'name', v_student.name,
        'program', v_student.program,
        'degreeLevel', v_student.degree_level,
        'batch', v_student.batch
    );
end;
$$;

revoke execute on function public.student_roll_status(text, text) from public, anon, authenticated;
grant execute on function public.student_roll_status(text, text) to service_role;

-- ---------------------------------------------------------------
-- Signup hook: roll accounts get their profile from the roster.
-- The roll comes from app_metadata (admin API only), never user metadata.
-- ---------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_meta    jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
    v_roll    text  := nullif(btrim(coalesce(new.raw_app_meta_data, '{}'::jsonb) ->> 'roll_no'), '');
    v_name    text  := btrim(coalesce(v_meta ->> 'display_name', v_meta ->> 'name', ''));
    v_deg     text  := upper(nullif(btrim(v_meta ->> 'degree_level'), ''));
    v_spec    text  := upper(nullif(btrim(v_meta ->> 'specialization'), ''));
    v_student public.students%rowtype;
    v_ok      boolean;
begin
    if v_roll is not null then
        select * into v_student from public.students where roll_no = v_roll;
        if found then
            v_name := v_student.name;
            v_deg  := v_student.degree_level;
            v_spec := v_student.program;
        else
            v_roll := null;
        end if;
    end if;
    if v_name = '' then
        v_name := split_part(new.email, '@', 1);
    end if;
    v_ok := coalesce(public.is_cohort_valid(v_deg, v_spec), false);

    insert into public.profiles (id, display_name, email, degree_level, specialization, student_id, roll_no)
    values (
        new.id,
        left(coalesce(nullif(v_name, ''), 'player'), 40),
        new.email,
        case when v_ok then v_deg end,
        case when v_ok then v_spec end,
        v_roll,
        v_roll
    )
    on conflict (id) do nothing;

    begin
        perform public.grant_starter_pack(new.id);
    exception when others then
        raise warning 'grant_starter_pack failed for %: %', new.id, sqlerrm;
    end;

    return new;
end;
$$;

revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- ---------------------------------------------------------------
-- Profile guard: roll_no is never player-editable; roll accounts also keep
-- the student id and cohort the roster gave them.
-- ---------------------------------------------------------------
create or replace function public.guard_profile_update()
returns trigger
language plpgsql
as $$
begin
    if current_user in ('anon', 'authenticated') and not public.is_admin() then
        if new.id is distinct from old.id
           or new.email is distinct from old.email
           or new.role is distinct from old.role
           or new.experience is distinct from old.experience
           or new.banned is distinct from old.banned
           or new.banned_at is distinct from old.banned_at
           or new.created is distinct from old.created
           or new.roll_no is distinct from old.roll_no then
            raise exception 'Players may only edit display name, avatar, student id, cohort and onboarding fields'
                using errcode = '42501';
        end if;
        if old.roll_no is not null
           and (new.student_id is distinct from old.student_id
                or new.degree_level is distinct from old.degree_level
                or new.specialization is distinct from old.specialization) then
            raise exception 'Roll number accounts take their student id and cohort from the roster'
                using errcode = '42501';
        end if;
    end if;
    -- level is always derived (trg_profiles_sync_level only fires on experience changes)
    new.level := public.compute_level(new.experience);
    return new;
end;
$$;

revoke execute on function public.guard_profile_update() from public, anon, authenticated;

